L5_1.m_Talk_KOREA = "가긴 어딜 가! 이 바보야! 그러다 큰일나!"
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "どこ行くんだよ！　このバカ！　大怪我するかもしれないよ！"
L5_1.m_Talk_ENG = "What are you doing?! You're gonna hurt, you fool!"
