L8_1.m_Pos = "L"
L8_1.m_Talk_KOREA = "감속 장치는 작동하는 것 같지만 가속도가 점점 붙고 있어."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "減速装置は作動してるみたいだけど、どんどん加速度が増してる。"
L8_1.m_Talk_ENG = "The decelerator seems to be working, but we're still gaining speed."
L8_1.m_Talk_TWN = "雖然有啟動減速裝置，但速度卻越來越快。"
L8_1.m_Talk_THA = "ตัวชะลอความเร็วเหมือนจะยังทำงานได้นะ แต่ความเร็วเราก็เพิ่มขึ้นเรื่อยๆ อยู่ดี"
L8_1.m_Talk_VTN = "Bộ giảm tốc dường như đang hoạt động, nhưng chúng ta vẫn đang tăng tốc."
L8_1.m_Talk_SCN = "减速装置，启动了，但加速度依旧逐渐增大。"
L8_1.m_Talk_DEU = "Der Entschleuniger scheint zu funktionieren, aber wir nehmen immer noch Fahrt auf."
L8_1.m_Talk_FRA = "Le décélérateur a l'air de fonctionner et pourtant, on continue de gagner de la vitesse."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "NEVERLAND_ACT3_INTERLUDE4@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 4600313
L9_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "PUPPET_NPC_SUPPLEMENT_NULL"
L9_1.m_Pos = "L"
L9_1.m_Talk_KOREA = "이 상태로 계속 가면 지면에 충돌할 때 우리 모두 도로시 다리 꼴이 날 거야."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "このままずっと行くと、地面に衝突する時にワタシたちもみんなドロシーの足のようになるはずだよ。"
L9_1.m_Talk_ENG = "At this rate, we're all going to end up like Dorothy's legs when it crashes into the ground."
L9_1.m_Talk_TWN = "再這樣下去，撞到地面時，我們全都會像桃樂絲的腿一樣。"
L9_1.m_Talk_THA = "ถ้าเป็นแบบนี้ ตกถึงพื้นเมื่อไหร่เราพบจุดจบเหมือนขาโดโรทีแน่"
L9_1.m_Talk_VTN = "Với tốc độ này, tất cả chúng ta sẽ giống như đôi chân của Dorothy khi nó cắm xuống đất."
L9_1.m_Talk_SCN = "按照计算，撞击地面的时候，我们会，和多萝西的腿一样碎成渣。"
L9_1.m_Talk_DEU = "Bei dieser Geschwindigkeit werden wir alle wie Dorothys Beine enden, wenn es in den Boden einschlägt."
L9_1.m_Talk_FRA = "À ce rythme, on va tous finir comme les jambes de Dorothée."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "NEVERLAND_ACT3_INTERLUDE4@10#Talk"
L10_1.m_CutScenProcessKey = 10
