L10_1.m_Pos = "R"
L10_1.m_Crash = 10
L10_1.m_Talk_KOREA = "자기가 이렇게 만들어 놓았으면서 말은……! 그럼 어서 빠져나가야지!"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "自分がやっておきながら……！　じゃあ、早く抜け出ないと！"
L10_1.m_Talk_ENG = "Wow... You did this to me, you know? Whatever, let's get out of here then!"
L10_1.m_Talk_TWN = "就是你把我弄成這樣的還敢講……！還是快離開這裡吧！"
L10_1.m_Talk_THA = "โห... ขาฉันนี่ฝีมือเธอนะรู้ตัวมั้ย? ช่างเหอะ เราหนีออกจากที่นี่กันดีกว่า!"
L10_1.m_Talk_VTN = "Wow... Cậu đã làm thế với tôi đấy, báo quá báo? Sao cũng được, hãy ra khỏi đây thôi!"
L10_1.m_Talk_SCN = "明明是你给我弄成这样的，还说……！那得赶紧逃出去啊！"
L10_1.m_Talk_DEU = "Wow ... Das hast du mir doch angetan oder hast du das etwa schon vergessen? Wie dem auch sei, lasst uns schnell von hier abhauen!"
L10_1.m_Talk_FRA = "Et la faute à qui, hein ? Quoi qu'il en soit, on doit se tailler d'ici !"
