L16_1.m_Talk_KOREA = "완전히 넋이 나간 상태야. 아까부터 미친 듯이 웃고만 있어."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "完全に正気を失ってる。さっきからずっと狂ったように笑ってるんだ。"
L16_1.m_Talk_ENG = "She's gone insane. All she does is laugh like crazy."
L16_1.m_Talk_TWN = "精神狀態不太好，從剛才就像發狂似地狂笑。"
L16_1.m_Talk_THA = "เธอเสียสติไปแล้ว เอาแต่หัวเราะเหมือนคนบ้าเลย"
L16_1.m_Talk_VTN = "Chị ấy mất trí rồi. Tất cả những gì chị ấy làm là cười hóa điên."
L16_1.m_Talk_SCN = "她已经彻底疯了。从刚才开始就在狂笑。"
L16_1.m_Talk_DEU = "Sie hat den Verstand verloren. Alles, was sie tut, ist wie verrückt zu lachen."
L16_1.m_Talk_FRA = "Elle a complètement perdu la tête. Elle n'arrête pas de rire comme un méchant de série B."
