L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_IDLE"
L20_1.m_CharStrID = "RUNNER_OZ_NULL_NULL"
L20_1.m_Pos = "R"
L20_1.m_Talk_KOREA = "기운내. 네가 사과할 일이 아니야, 시그마."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "頑張って。シグマが謝ることじゃないよ。"
L20_1.m_Talk_ENG = "Chin up. You don't have to apologize to us, Sigma."
L20_1.m_Talk_TWN = "打起精神來，這不是你的錯，西格瑪。"
L20_1.m_Talk_THA = "เงยหน้าขึ้นน่า เธอไม่ต้องขอโทษเราซะหน่อยซิกมา"
L20_1.m_Talk_VTN = "Đừng lo. Cậu không cần phải xin lỗi chúng tôi, Sigma."
L20_1.m_Talk_SCN = "打起精神来，这件事不是你的错，西格玛。"
L20_1.m_Talk_DEU = "Kopf hoch. Du musst dich nicht bei uns entschuldigen, Sigma."
L20_1.m_Talk_FRA = "Non Sigma, tu ne nous dois aucune excuse."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "NEVERLAND_ACT3_INTERLUDE4@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 4600313
L21_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "PUPPET_NPC_SUPPLEMENT_NULL"
L21_1.m_Pos = "L"
L21_1.m_Talk_KOREA = "지금은 이 함선에서 탈출하는 게 먼저야. 탈출선이 있는 데로 가자."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "今はこの艦船から脱出するのが先だよ。脱出船のあるところに行こう。"
L21_1.m_Talk_ENG = "Getting off this ship is our number one priority. Let's head to the escape pods."
L21_1.m_Talk_TWN = "現在最重要的是趕快逃離這艘艦船，先去有逃生船的地方吧！"
L21_1.m_Talk_THA = "การออกไปจากยานลำนี้คือเรื่องสำคัญอันดับหนึ่ง รีบไปที่กระสวยลี้ภัยกันเถอะ"
L21_1.m_Talk_VTN = "Ra khỏi con tàu này là ưu tiên số một của chúng ta. Hãy đi đến chỗ kén thoát hiểm đi."
L21_1.m_Talk_SCN = "当务之急，要先从舰船上逃出去。得找到逃生舱。"
L21_1.m_Talk_DEU = "Das Verlassen des Schiffs hat für uns oberste Priorität. Wir müssen zu den Rettungskapseln."
L21_1.m_Talk_FRA = "Pour l'instant, on doit trouver un moyen de quitter ce vaisseau. Il y a pas des nacelles de sauvetage, ici ?"
