L23_1 = {}
L23_1.m_CutScenKey_Talk = "NEVERLAND_ACT3_INTERLUDE4@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 4600313
L23_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_DESPAIR"
L23_1.m_CharStrID = "SWORD_OZ_NULL_NULL"
L23_1.m_Pos = "C"
L23_1.m_Talk_KOREA = "사람들이 이렇게나 많은데…… 제때 탈 수 있을까?"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "こんなに人が多いのに……乗れるのかな？"
L23_1.m_Talk_ENG = "But there are so many people here... Do you think we'll be able to get on one in time?"
L23_1.m_Talk_TWN = "人這麼多……搭得到嗎？"
L23_1.m_Talk_THA = "แต่ที่นี่มีคนเต็มไปหมดเลยนะ... เราจะไปกันทันเหรอ?"
L23_1.m_Talk_VTN = "Nhưng có rất nhiều người ở đây... Cậu có nghĩ chúng ta cứu được hết tất cả họ một lượt không?"
L23_1.m_Talk_SCN = "人这么多……能全都坐下吗？"
L23_1.m_Talk_DEU = "Aber es sind so viele Leute hier ... Glaubst du, wir können noch eine abbekommen?"
L23_1.m_Talk_FRA = "Mais avec tout ce monde... tu crois qu'il restera de la place pour nous ?"
