L27_1 = {}
L27_1.m_CutScenKey_Talk = "NEVERLAND_ACT3_INTERLUDE4@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 4600313
L27_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_StartFXSoundName = "FX_COMBAT_ALL_FOOT_STEP_LANDING_SMALL_02"
L27_1.m_CharStrID = "PARK_NPC_HAVEN_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "……저희가 안내해 드리겠습니다. 손님 여러분."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "……私たちがご案内いたします。お客様。"
L27_1.m_Talk_ENG = "Dear guests... We will guide you."
L27_1.m_Talk_TWN = "……各位客人，我帶你們去吧。"
L27_1.m_Talk_THA = "ผู้โดยสารที่เคารพทั้งหลาย... ผมจะนำทางให้เอง"
L27_1.m_Talk_VTN = "Kính thưa quý khách... Chúng tôi sẽ hướng dẫn quý khách."
L27_1.m_Talk_SCN = "……我们给诸位带路，几位客人。"
L27_1.m_Talk_DEU = "... Liebe Gäste. Wir werden Sie führen."
L27_1.m_Talk_FRA = "Suivez-moi, chers invités. je vais vous guider."
