L29_1.m_Talk_KOREA = "<color=#ffd34c>그 목소리는…… 설마 휴스턴?</color>"
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "<color=#ffd34c>その声は……まさかヒューストン？</color>"
L29_1.m_Talk_ENG = "<color=#ffd34c>That voice... Is that Huston?</color>"
L29_1.m_Talk_TWN = "<color=#ffd34c>這個聲音是……休士頓？</color>"
L29_1.m_Talk_THA = "<color=#ffd34c>เสียงนั่น... ฮิวสตันเหรอ?</color>"
L29_1.m_Talk_VTN = "<color=#ffd34c>Giọng nói đó... Có phải Huston không?</color>"
L29_1.m_Talk_SCN = "<color=#ffd34c>这个声音……难道是休斯顿？</color>"
L30_1 = "<color=#ffd34c>Diese Stimme ... Ist das Huston?</color>"
L29_1.m_Talk_DEU = L30_1
L30_1 = "<color=#ffd34c>Cette voix... Huston ?</color>"
L29_1.m_Talk_FRA = L30_1
