L32_1.m_Face = "UNIT_HATE"
L32_1.m_CharStrID = "SWORD_OZ_NULL_NULL"
L32_1.m_Pos = "R"
L32_1.m_Crash = 10
L33_1 = "무슨 낯으로 우리 앞에 나타난 거야? 우리가 누구 때문에 이 고생을 했는데!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "どの面下げて私たちの前に現れたの？　誰のせいで苦労してると思ってる！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "What are you up to this time?! We're in this mess because of you!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "你還有什麼臉出現在我們面前？是誰害我們這麼辛苦的！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "คราวนี้วางแผนอะไรอีกล่ะ?! เราต้องมาวุ่นวายแบบนี้ก็เพราะคุณนะ!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Lần này anh định làm gì?! Chúng tôi gặp rác rối này đều là vì anh!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "你有什么脸出现在我们面前？我们是因为谁才会吃这些苦头的！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Was hast du denn dieses Mal vor?! Wegen dir stecken wir überhaupt erst in diesem Schlamassel!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Qu'est-ce que tu nous veux, encore ? Tu crois pas que tu nous a causé assez de souci comme ça ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "NEVERLAND_ACT3_INTERLUDE4@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 4600313
L33_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "RUNNER_OZ_NULL_NULL"
L33_1.m_Pos = "L"
L34_1 = "그만해, 리온. 저 사람 총에 맞았잖아."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "やめな、リオン。あの人も銃に撃たれてる。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Enough, Liona. He's been shot."
L33_1.m_Talk_ENG = L34_1
L34_1 = "萊恩，別說了，你沒看到他中槍了嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "พอเถอะลีโอนา เขาโดนยิงนะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Đủ rồi, Liona. Anh ấy đã bị bắn."
L33_1.m_Talk_VTN = L34_1
L34_1 = "别说了，莱恩。那个人中枪了。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Hör auf, Leonie. Er wurde angeschossen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Arrête, Liona. Tu vois pas qu'il est blessé ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "NEVERLAND_ACT3_INTERLUDE4@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 4600313
L34_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "SWORD_OZ_NULL_NULL"
L34_1.m_Pos = "R"
L34_1.m_Crash = 20
L35_1 = "하지만……!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "でも……！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "But...!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "可是……！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "แต่ว่า...!"
L34_1.m_Talk_THA = L35_1
L35_1 = "Nhưng mà...!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "但是……！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Aber ...!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Mais... !"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "NEVERLAND_ACT3_INTERLUDE4@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 4600313
L35_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "RUNNER_OZ_NULL_NULL"
L35_1.m_Pos = "L"
L36_1 = "됐어. 이미 한 방 먹은 녀석을 뭐 하러 또 걷어차."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "もういい。すでに一発食らってるやつをまた蹴とばす必要はないよ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "It's okay. There's no reason to kick someone who's already down."
L35_1.m_Talk_ENG = L36_1
L36_1 = "好了，既然他已經受到教訓，就不需要再對他落井下石。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ไม่เป็นไรหรอก คนล้มแล้วเราก็ไม่จำเป็นต้องไปข้ามนะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Được rồi. Đừng làm chuyện bỏ đá xuống giếng."
L35_1.m_Talk_VTN = L36_1
L36_1 = "算了，那家伙已经中枪了，干嘛还踢他。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Schon gut. Es gibt keinen Grund, jemanden zu treten, der bereits am Boden liegt."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Ça va, je te dis. On ne tire pas sur un type déjà à terre."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 4600313
L36_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L36_1.m_bWaitClick = false
L36_1.m_fWaitTime = 0
L36_1.m_bClear = true
L37_1 = {}
L38_1 = "NEVERLAND_ACT3_INTERLUDE4@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 4600313
L37_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "PARK_NPC_HAVEN_NULL"
L37_1.m_Pos = "C"
L38_1 = "변명하지는 않겠습니다. 형님을 위해 기생충을 제거할 수 있다면 다른 건 상관없다고 생각했으니까요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "言い訳はしません。兄貴のために寄生虫を除去することさえできれば、他はどうでもいいと思っていましたので。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I won't make excuses. I thought that nothing else would matter if I could get rid of the parasites for Mr. Haven."
L37_1.m_Talk_ENG = L38_1
L38_1 = "我無話可說，只要能替大哥除掉寄生蟲，其他我都無所謂。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ผมจะไม่แก้ตัวอะไรหรอกนะ เพราะผมไม่สนใจอะไรทั้งสิ้น ขอแค่กำจัดปรสิตพ้นคุณแฮฟเวนได้เท่านั้น"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi sẽ không tự biện hộ cho bản thân. Tôi đã tưởng rằng sẽ không có vấn đề gì khi loại bỏ ký sinh trùng cho ông Haven."
L37_1.m_Talk_VTN = L38_1
L38_1 = "这一点我无法反驳。但我认为只要能为老大除掉寄生虫，其他的都无所谓了。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ich werde mich nicht herausreden. Ich dachte, nichts anderes wäre von Bedeutung, als für Boss Haven die Parasiten loszuwerden."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Votre amie a raison, mes actes sont inexcusables. Je pensais que rien d'autre n'importait, tant que je me débarrassais des parasites qui avaient envahi la propriété de M. Haven."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
