L40_1 = "<color=#ffd34c>저 바보가…….</color>"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "<color=#ffd34c>あのバカが……</color>"
L39_1.m_Talk_JPN = L40_1
L40_1 = "<color=#ffd34c>You fool...</color>"
L39_1.m_Talk_ENG = L40_1
L40_1 = "<color=#ffd34c>那個傻瓜……</color>"
L39_1.m_Talk_TWN = L40_1
L40_1 = "<color=#ffd34c>เจ้าโง่เอ๊ย...</color>"
L39_1.m_Talk_THA = L40_1
L40_1 = "<color=#ffd34c>Anh ngốc quá... </color>"
L39_1.m_Talk_VTN = L40_1
L40_1 = "<color=#ffd34c>这个傻瓜……</color>"
L39_1.m_Talk_SCN = L40_1
L40_1 = "<color=#ffd34c>Du Idiot ...</color>"
L39_1.m_Talk_DEU = L40_1
L40_1 = "<color=#ffd34c>Huston, tu... imbécile...</color>"
L39_1.m_Talk_FRA = L40_1
