L43_1 = "NEVERLAND_ACT3_INTERLUDE4@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 4600313
L42_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_DESPAIR"
L42_1.m_CharStrID = "RESORT_NPC_HAVEN_NULL"
L42_1.m_Pos = "R"
L43_1 = "그래서 이 멍청이가 혼자 다 안고 가겠답시고 날 독방에 처박아 둔 거고."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "それでこのバカが自分が責任を持つとか言って、私を独房に閉じ込めたわけね。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "And that's why this moron locked me up in a cell so he could take all the blame."
L42_1.m_Talk_ENG = L43_1
L43_1 = "所以這個笨蛋就把我關在房裡，打算自己承擔一切。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "และเพราะแบบนั้นตาโง่นี่เลยขังฉันไว้ในห้องเนี่ย ตัวเองจะได้รับผิดทั้งหมดไปคนเดียว"
L42_1.m_Talk_THA = L43_1
L43_1 = "Và đó là lý do tại sao tên ngốc này nhốt tôi vào phòng giam để hắn có thể nhận hết mọi tội lỗi."
L42_1.m_Talk_VTN = L43_1
L43_1 = "所以，这个笨蛋说要一个人承担，把我关进了小黑屋里。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Und deshalb hat mich dieser Idiot in eine Zelle gesperrt, damit er die ganze Schuld auf sich nehmen konnte."
L42_1.m_Talk_DEU = L43_1
L43_1 = "... c'est pourquoi ce crétin m'a enfermé dans une cellule au lieu de me tuer. Pour porter le chapeau tout seul."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "NEVERLAND_ACT3_INTERLUDE4@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 4600313
L43_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Face = "UNIT_SERIOUS"
L43_1.m_CharStrID = "RESORT_NPC_HAVEN_NULL"
L43_1.m_Pos = "R"
L44_1 = "일단 감속 장치는 어떻게 작동시키긴 했는데, 그것만 가지고 추락을 막기에는 무리야."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "とりあえずなんとか減速装置を作動させたけど、それだけでは墜落を止められない。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I've restarted the decelerator, but it's not enough to stop the ship from crashing."
L43_1.m_Talk_ENG = L44_1
L44_1 = "雖然已經想辦法啟動減速裝置，但光靠那個還是無法阻止艦船迫降。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันเดินเครื่องตัวชะลอความเร็วใหม่แล้วนะ แต่ก็ยังไม่พอให้ยานไม่ตก"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi đã khởi động lại bộ giảm tốc, nhưng vẫn không đủ để ngăn con tàu lao xuống dưới."
L43_1.m_Talk_VTN = L44_1
L44_1 = "我已经想办法启动了减速装置，但只靠那个没办法阻止舰船坠落。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich habe den Entschleuniger neu gestartet, aber das reicht nicht aus, um den Absturz des Schiffes zu verhindern."
L43_1.m_Talk_DEU = L44_1
L44_1 = "J'ai redémarré le décélérateur, mais ça ne suffira pas."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "NEVERLAND_ACT3_INTERLUDE4@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 4600313
L44_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "DANCE_NPC_HAVEN_NULL"
L44_1.m_Pos = "L"
L45_1 = "조직원들 모두가 나서서 손님들부터 탈출선에 태우고 있다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "組織員総出でお客様から先に脱出船に乗せている。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "All the other members are guiding our guests to the escape pods."
L44_1.m_Talk_ENG = L45_1
L45_1 = "現在所有員工全都在引導客人搭上逃生船，"
L44_1.m_Talk_TWN = L45_1
L45_1 = "สมาชิกเราคนอื่นๆ กำลังนำทางผู้โดยสารไปที่กระสวยลี้ภัยแล้ว"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tất cả thành viên khác đang dẫn khách của chúng ta đến chỗ kén thoát hiểm."
L44_1.m_Talk_VTN = L45_1
L45_1 = "组织成员全都出动了，正在让客人们先坐上逃生舱。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Alle anderen Mitglieder führen unsere Gäste zu den Rettungskapseln."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Les autres membres du personnel sont en train de guider les passagers vers les nacelles..."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "NEVERLAND_ACT3_INTERLUDE4@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 4600313
L45_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "DANCE_NPC_HAVEN_NULL"
L45_1.m_Pos = "L"
L46_1 = "하지만 시간이 부족해. 게다가 도시에 헤이븐 랜드가 추락하면 큰일이 벌어질 거야."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "だが時間が足りない。しかも都市にヘイブンランドが墜落すると大変なことになるぞ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "But there's not enough time. In addition, if Havenland crashes into the city, things are going to become much worse."
L45_1.m_Talk_ENG = L46_1
L46_1 = "但時間不夠，而且天堂樂園要是真的迫降的話，那個城市會完蛋的。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แต่เวลามีไม่พอ แถมถ้าแฮฟเวนแลนด์ตกใส่เมือง อะไรๆ จะยิ่งแย่กว่ามาก"
L45_1.m_Talk_THA = L46_1
L46_1 = "Nhưng không đủ thời gian. Ngoài ra, nếu Havenland đâm xuống thành phố, mọi thứ sẽ trở nên tồi tệ hơn nhiều."
L45_1.m_Talk_VTN = L46_1
L46_1 = "但是时间不够，而且海文乐园掉进城市里的话就糟了。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Aber die Zeit reicht nicht aus. Und wenn Havenland in die Stadt einschlägt, wird es verheerende Folgen haben."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Mais le temps joue contre nous. Et si Havenland s'écrase sur la ville, ça risque d'être une véritable tragédie."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
