L48_1 = "NEVERLAND_ACT3_INTERLUDE4@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 4600313
L47_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_DESPAIR"
L47_1.m_CharStrID = "PARK_NPC_HAVEN_NULL"
L47_1.m_Pos = "C"
L48_1 = "모두 제 탓입니다. 제가 해결할 수 있다는 오만함 탓에 형님의 파라다이스를……."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "全て私のせいです。自力で解決できるという傲慢で、兄貴のパラダイスを……"
L47_1.m_Talk_JPN = L48_1
L48_1 = "It's all my fault. Because of my arrogance I thought I could take care of this on my own. But in the end, your paradise..."
L47_1.m_Talk_ENG = L48_1
L48_1 = "這全都怪我太驕傲，自以為能解決，才會害大哥的樂園……"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ทั้งหมดเป็นความผิดผมเอง ผมผยองว่าตัวเองทำทั้งหมดคนเดียวได้ แต่สุดท้าย สวรรค์ของเธอกลับต้อง..."
L47_1.m_Talk_THA = L48_1
L48_1 = "Tất cả là lỗi của tôi. Vì sự kiêu ngạo của tôi, tôi nghĩ mình có thể giải quyết việc này một mình. Nhưng cuối cùng, thiên đường của cô..."
L47_1.m_Talk_VTN = L48_1
L48_1 = "都是我的错，以为可以独自解决这件事。这种傲慢的态度，最终毁掉了老大的海文乐园……"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Es ist alles meine Schuld. Aufgrund meiner Arroganz dachte ich, ich könnte mich alleine darum kümmern. Aber am Ende ist Boss Havens Paradies ..."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Tout est de ma faute. Avec mon arrogance, j'ai cru que je pourrais gérer la situation tout seul. Mais à cause de moi, votre paradis va..."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
