L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 4600313
L50_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_HATE"
L50_1.m_CharStrID = "RESORT_NPC_HAVEN_NULL"
L50_1.m_Pos = "R"
L51_1 = "어휴. 넌 진짜 이번 한 번만 누나가 봐 준다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "まったく。このお姉さんが一度だけ許してやる。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Ugh... You fool, I will forgive you this once."
L50_1.m_Talk_ENG = L51_1
L51_1 = "真是的，姊姊這次就先不跟你計較！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "โธ่... ไม่ต้องห่วงน่า คราวนี้จะยกให้หนนึง"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ugh... Đừng lo nữa, lần này tôi sẽ tha thứ cho anh."
L50_1.m_Talk_VTN = L51_1
L51_1 = "唔……就这一次，原谅你了哦，小弟弟——"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Urgh. Ich werde dir dieses Mal vergeben."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Bah... Je ferme les yeux pour cette fois. Mais c'est la dernière !"
L50_1.m_Talk_FRA = L51_1
