L1_1.m_Pos = "L"
L2_1 = "그거 다행이군. 두 번째는 없을지도 모른다는 게 문제지만."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "それはよかったな。二度目はないかもしれなということが問題だが。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I’m glad to hear that. Although, there might not be another time for us."
L1_1.m_Talk_ENG = L2_1
L2_1 = "算你幸運，只是不知道還會有下次嗎？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ได้ยินแบบนั้นก็โล่งใจ ถึงเราอาจจะไม่มีคราวหน้าแล้วก็เถอะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tôi rất vui khi nghe điều đó. Mặc dù, có thể không còn lần khác cho chúng ta nữa."
L1_1.m_Talk_VTN = L2_1
L2_1 = "你承认了就好。问题是现在这种情况，或许也没有第二次了。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ich bin froh, das zu hören. Obwohl es für uns möglicherweise kein nächstes Mal geben wird."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Je vous remercie. Mais pour moi, il n'y aura pas de prochaine fois."
L1_1.m_Talk_FRA = L2_1
