L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "R"
L8_1.m_Crash = 20
L9_1 = "다 없애 버릴 거야!! 다 같이 죽을 거라고!!"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "全部消してやるわ！！　みんな死ねばいいのよ！！"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I'll destroy you all! You're going down with me!!"
L8_1.m_Talk_ENG = L9_1
L9_1 = "我要把一切都毀掉！！我要把你們全殺掉！！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ฉันจะทำลายพวกแกให้หมด! พวกแกต้องตกไปกับฉันนี่แหละ!!"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tao sẽ hủy diệt tất cả bọn mày! Bọn mày sẽ cùng chết với tao!!"
L8_1.m_Talk_VTN = L9_1
L9_1 = "全部毁掉！！全都一起去死吧！"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich werde euch alle zerstören! Wir werden alle zusammen sterben!!"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Je vais tout détruire, tout ! Vous allez tous mourir avec moi !!"
L8_1.m_Talk_FRA = L9_1
