L9_1.m_Pos = "L"
L9_1.m_Crash = 30
L10_1 = "누나! 정신 차려! 제발 그만해!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "姉さん！　しっかりして！　お願いだからやめてよ！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Sis! Stop this! Please!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "姊姊！你清醒一點！我拜託你！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "พี่ครับ! หยุดเถอะครับ! ขอร้องล่ะ!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Chị! Dừng thứ này lại đi! Làm ơn!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "姐姐！你醒醒！求求你停手吧！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Schwester! Hör auf damit! Bitte!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Soeurette ! Arrête cette folie, je t'en supplie !!"
L9_1.m_Talk_FRA = L10_1
