L11_1 = "놔…… 이거 놔…… 놓으라고……!"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "放して……放して……放しなさいったら……！"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Let... go...! I said, LET GO...!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "放……放開我……我叫你放開……！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ปล่อย... นะ...! บอกให้ปล่อยไง...!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Đi... đi nào...! Tao đã nói là ĐI NÀO...!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "放开……放开我……快放开我……！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Lass los ...! Ich sagte, du sollst mich loslassen ...!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Lâche... Lâche-moi, crétin !!"
