L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "HAVEN_HAVEN_NULL_ROOT"
L11_1.m_Pos = "L"
L12_1 = "누나, 나도 누나와는 이제 두 번 다시 엮이고 싶지 않아."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "姉さん、僕ももう二度と姉さんとは関わりたくない。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Sis, I don't want anything to do with you anymore."
L11_1.m_Talk_ENG = L12_1
L12_1 = "姊姊，我也不想再和你有任何牽扯。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "พี่ครับ ผมไม่อยากทำอะไรร่วมกับพี่อีกแล้ว"
L11_1.m_Talk_THA = L12_1
L12_1 = "Chị ơi, em không muốn dính dáng gì đến chị nữa."
L11_1.m_Talk_VTN = L12_1
L12_1 = "姐姐，我也不想再跟姐姐继续纠缠下去了。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Schwester, ich möchte nichts mehr mit dir zu tun haben."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Moi non plus je ne veux plus jamais te revoir, tu sais ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "NEVERLAND_ACT3_INTERLUDE4@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 4600313
L12_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "HAVEN_HAVEN_NULL_ROOT"
L12_1.m_Pos = "L"
L13_1 = "하지만…… 누나 말만 믿고 놀기만 하던 내 잘못도 분명히 있어."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "でも……姉さんの言葉だけを信じて、遊んでばかりだった僕の責任もあるんだ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Although I admit it was my fault to entrust you with everything while I was fooling around."
L12_1.m_Talk_ENG = L13_1
L13_1 = "但是……我也有錯，因為我只顧著玩，你說什麼我都信。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ถึงผมจะยอมรับว่าเป็นความผิดตัวเอง ที่วางใจให้พี่ทำทุกอย่าง ทั้งที่ตัวเองโดนหลอกมาตลอดก็เถอะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Mặc dù em thừa nhận rằng đó là lỗi của em khi phó thác mọi thứ cho chị trong khi em mãi mơ hồ."
L12_1.m_Talk_VTN = L13_1
L13_1 = "但是……一味地相信姐姐，只知道玩的我肯定也有错。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Obwohl ich zugeben muss, dass ich es falsch von mir war, dir alles anzuvertrauen, während ich nur herumgespielt habe."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Je n'aurais jamais dû te faire confiance. Et dire que je passais mon temps à m'amuser... tout est de ma faute."
L12_1.m_Talk_FRA = L13_1
