L18_1.m_Pos = "R"
L18_1.m_bCharHologramEffect = true
L18_1.m_Crash = 15
L19_1 = "방금 추락을 막겠다고 한 거야? 시그마가?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "墜落を止めるって言ったの？　シグマが？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Did Sigma just say she'll stop the ship from crashing?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "西格瑪，你剛說你要阻止艦船迫降嗎？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เมื่อกี้ซิกมาบอกว่าเธอจะหยุดไม่ให้ยานตกเหรอ?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Có phải Sigma vừa nói cô ấy sẽ ngăn con tàu này đâm xuống phải không?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "呃？你是说你有办法停下舰船吗？西格玛？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Hat Sigma gerade gesagt, dass sie das Schiff vorm Absturz bewahren wird?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Hein ? Elle compte empêcher le vaisseau de s'écraser ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "NEVERLAND_ACT3_INTERLUDE4@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 4600313
L19_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "NEWCOMER_NPC_DREAM_NULL"
L19_1.m_Pos = "L"
L20_1 = "아무리 애라도 그렇지, 이럴 때는 진지하게 생각해."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "子どもとはいえ、こういう時には真剣に考えないと。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Stop kidding around and be serious about this."
L19_1.m_Talk_ENG = L20_1
L20_1 = "小孩子別亂說話，這種時候不要開玩笑！"
L19_1.m_Talk_TWN = L20_1
L20_1 = "หยุดล้อเล่นแล้วจริงจังเรื่องนี้กันทีเถอะ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Đừng có đùa nữa và nghiêm túc đi."
L19_1.m_Talk_VTN = L20_1
L20_1 = "就算是个孩子，这种时候也要认真点。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Jetzt ist nicht die Zeit, Scherze zu reißen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Arrête un peu de plaisanter, la situation est sérieuse."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "NEVERLAND_ACT3_INTERLUDE4@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 4600313
L20_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "NEWCOMER_NPC_DREAM_NULL"
L20_1.m_Pos = "L"
L21_1 = "헤이븐 랜드는 보통 함선보다 몇 배는 커. 가능할 리 없잖아."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "ヘイブンランドは普通の艦船より何倍も大きいんだよ。できるわけないじゃん。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "There’s no way that's possible. Havenland is massive. Many times bigger than any ordinary ship."
L20_1.m_Talk_ENG = L21_1
L21_1 = "天堂樂園比普通的艦船還要大上好幾倍，你怎麼有辦法阻止。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "มันเป็นไปไม่ได้หรอกนะ แฮฟเวนแลนด์ใหญ่โตมโหฬารขนาดนี้ ใหญ่กว่ายานทั่วไปไม่รู้กี่เท่า"
L20_1.m_Talk_THA = L21_1
L21_1 = "Không thể nào như vậy được. Havenland quá khổng lồ. Lớn hơn nhiều lần so với bất kỳ con tàu bình thường nào."
L20_1.m_Talk_VTN = L21_1
L21_1 = "海文乐园比一般的舰船大好几倍。这根本不可能！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Unmöglich. Havenland ist riesig. Es ist um ein Vielfaches größer als jedes gewöhnliche Schiff."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Tu arriveras jamais à arrêter Havenland, tu as vu la taille du truc ? Il est bien plus grand qu'un vaisseau ordinaire..."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
