L23_1 = "NEVERLAND_ACT3_INTERLUDE4@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 4600313
L22_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_SERIOUS"
L22_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L22_1.m_Pos = "C"
L23_1 = "아냐, 할 수 있어. 아빠가 힘을 사용하게 허락해 준 이유가 있을 거야."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ううん、できるよ。パパが力を使えるように許可してくれた理由があるはずだから。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "No, I can do it. Daddy gave me permission to use this power for a reason."
L22_1.m_Talk_ENG = L23_1
L23_1 = "是真的啦，我可以的。爸爸會答應讓我使用能力，一定是有原因的。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ไม่ค่ะ ฉันทำได้ พ่อมีเหตุผลที่อนุญาตให้ฉันใช้พลังนี้"
L22_1.m_Talk_THA = L23_1
L23_1 = "Không, tôi có thể làm được. Bố đã cho phép tôi sử dụng sức mạnh này là có lý do."
L22_1.m_Talk_VTN = L23_1
L23_1 = "不，我能做到。爸爸允许我使用力量应该都是有原因的。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Nein, ich kann es schaffen. Papa hat mir nicht ohne Grund die Erlaubnis gegeben, diese Kraft zu nutzen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Non, je peux le faire. Papa m'a donné la permission d'utiliser ce pouvoir pour une raison."
L22_1.m_Talk_FRA = L23_1
