L29_1 = "저 아래에, 더 많은 사람들이 있어……!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "あの下に、人がもっとたくさんいるんだ……！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "There are a lot of people below us...!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "下面的人更多……！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ข้างใต้เรามีคนเยอะแยะเลยนะ...!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Có rất nhiều người bên dưới chúng ta...!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "这底下，有那么多人……！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Es gibt viele Menschen unter uns ...!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "C'est encore plus dangereux pour les gens en dessous de nous..."
L28_1.m_Talk_FRA = L29_1
