L29_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L29_1.m_Pos = "C"
L29_1.m_bCharPinup = true
L30_1 = "모두에게 알려 줄 거야. 이런 나쁜 짓으로는 행복해질 수 없다는 걸."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "みんなに教えてあげるんだ。悪いことしては幸せになれないってことを。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I’m gonna show everyone. That you can't find happiness by doing bad things!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "我要告訴大家，用這種不好的行為是無法變幸福的！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันจะทำให้ทุกคนเห็นเอง ว่าถ้าทำไม่ดีก็ไม่มีทางมีความสุขหรอก!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi sẽ cho mọi người thấy rằng hạnh phúc không thể có được khi làm điều xấu xa!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "我要告诉所有人，这样做坏事是得不到幸福的。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ich werde es allen zeigen. Dass man sein Glück nicht dadurch findet, dass man schlechte Dinge tut!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Je vais leur montrer, à tout le monde. Que ce n'est pas en faisant le mal qu'on trouve le bonheur."
L29_1.m_Talk_FRA = L30_1
