L37_1 = "저, 정말이야? 시그마가 이 큰 함선을 혼자 막고 있다고?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ほ、本当？　シグマがこの大きい艦船を一人で止めてるってこと？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "I-is this for real? Sigma's stopping this huge ship all by herself?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "真…真的嗎？西格瑪自己阻止這麼大的艦船？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "จะ-จริงเหรอเนี่ย? ซิกมาหยุดยานลำเบ้อเริ่มด้วยตัวคนเดียวเนี่ยนะ?"
L36_1.m_Talk_THA = L37_1
L37_1 = "C-chuyện này là thật sao? Sigma định tự mình dừng con tàu khổng lồ này sao?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "真、真的吗？西格玛一个人把舰船停下了？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "W-wirklich? Sigma kann ganz alleine dieses riesige Schiff aufhalten?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Q-Quoi, vraiment ? Sigma a réussi à arrêter le vaisseau... toute seule ?"
L36_1.m_Talk_FRA = L37_1
