L40_1 = "NEVERLAND_ACT3_INTERLUDE4@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 4600313
L39_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L39_1.m_bWaitClick = true
