L39_1.m_CharStrID = "RESORT_NPC_HAVEN_NULL"
L39_1.m_Pos = "R"
L39_1.m_Crash = 20
L40_1 = "아무리 그래도 가능한 일이 있지! 공학자로서 인정 못 해!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "いくらなんでもあり得ない！　エンジニアとして認められない！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "How's that even possible?! As an engineer, I can't believe it!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "世界之大無奇不有！但理工科頭腦是無法理解的！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "มันเป็นไปได้ไงน่ะ?! ในฐานะที่เป็นวิศวกรนี่ฉันไม่อยากเชื่อเลยนะ!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Sao có thể được?! Là một kỹ sư, tôi không thể tin nổi!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "不管怎么说，这都不可能吧！不对不对，从工程学角度来说——这不可能！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Wie ist das überhaupt möglich?! Als Ingenieurin kann ich es nicht glauben!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Comment est-ce possible ?! En tant qu'ingénieure, je ne peux pas le croire !"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "NEVERLAND_ACT3_INTERLUDE4@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 4600313
L40_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "DANCE_NPC_HAVEN_NULL"
L40_1.m_Pos = "L"
L41_1 = "그런 건 나중에 차차 고민해. 지금은 탈출선으로 가는 게 먼저야."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "それは後で考えろ。今は脱出船に向かうのが先だ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Let's think about that later. Right now, we need to head to the escape pods."
L40_1.m_Talk_ENG = L41_1
L41_1 = "這種事等之後再傷腦筋吧，現在當務之急是趕快去找逃生船！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เรื่องนั้นค่อยคิดทีหลังเถอะ ตอนนี้เราต้องไปที่กระสวยลี้ภัยนะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Để đó nghĩ sau. Ngay bây giờ, chúng ta cần tới kén thoát hiểm."
L40_1.m_Talk_VTN = L41_1
L41_1 = "那个等以后再慢慢想吧。当务之急是先去逃生舱那里。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Lass uns später darüber nachdenken. Jetzt müssen wir uns auf den Weg zu den Rettungskapseln machen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "On verra ça plus tard. Vite, aux nacelles de sauvetage !"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
