L44_1.m_Pos = "C"
L44_1.m_bCharPinup = true
L45_1 = "어떡하지? 에너지가 너무 빨리 줄어들어! 오래 못 버티겠어!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "どうしよう？　エネルギー消耗が早すぎ！　長く持たない！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "What do I do? I’m losing energy too fast! I won't be able to hold on much longer!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "怎麼辦？能源正在快速減少！沒辦法撐太久的！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ทำไงดีเนี่ย? พลังงานหมดเร็วเกินไป! ทนนานกว่านี้ไม่ไหวแน่!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Mình làm gì đây? Mình đang hao hụt năng lượng quá nhanh! Mình sẽ không thể gắng gượng lâu hơn được nữa!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "怎么办？能量减少得太快了！我撑不了太久的！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Was soll ich bloß tun? Ich verliere zu schnell Energie! Ich werde es nicht mehr lange aufhalten können!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Comment faire ? Mes réservent d'énergie sont en train de se vider, je tiendrai pas longtemps !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
