L48_1 = "루루, 뭐 해!"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "ルル、何してるんだよ！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Lulu! Where do you think you're going?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "露露，你在幹嘛！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ลูลู! จะไปไหนของเธอน่ะ?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Lulu! Nhóc đang đi đâu thế?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "露露，你在干什么！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Lulu! Was denkst du, wo du hingehst?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Lulu ? Qu'est-ce que tu fais ?"
L47_1.m_Talk_FRA = L48_1
