L49_1 = "NEVERLAND_ACT3_INTERLUDE4@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 4600313
L48_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "NEWCOMER_NPC_DREAM_NULL"
L48_1.m_Pos = "C"
L49_1 = "어서 와! 늦었다간 탈출선이 없을 수도 있어!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "早くおいで！　遅れたら脱出船がなくなっちゃう！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "C'mon! There might not be an escape pod left if we're late!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "快過來！萬一動作太慢會搭不到逃生船的！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "มานี่มา! ชักช้าจะไม่เหลือกระสวยลี้ภัยเอานะ!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Thôi nào! Có thể không còn kén thoát hiểm nào nếu chúng ta đến muộn!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "快过来！晚了可能就没有逃生舱了！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Lass uns gehen! Wenn wir zu spät kommen, ist möglicherweise keine Rettungskapsel mehr übrig!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Viens avec nous ! Si on attend trop, il n'y aura plus de place pour nous !"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
