L3_1 = "이 상황에 또야? 당장 죽게 생겼는데 악몽 꾸는 사람이 어디 있다고!"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "こんな状況でまた？　今すぐ死ぬかもしれないのに悪夢を見てる人なんていないよ！"
L2_1.m_Talk_JPN = L3_1
L3_1 = "That again?! No one's gonna have a nightmare when we're all about to plunge to our deaths!"
L2_1.m_Talk_ENG = L3_1
L3_1 = "這種時候還來？這種生死交關的時刻，誰有閒情逸致做惡夢啦！"
L2_1.m_Talk_TWN = L3_1
L3_1 = "พูดแบบนั้นอีกแล้วเหรอ?! ไม่มีใครเข้าฝันร้ายกันตอนหัวกำลังจะปักลงไปในความตายหรอกนะ!"
L2_1.m_Talk_THA = L3_1
L3_1 = "Lại nữa sao?! Sẽ không còn ai gặp ác mộng nữa khi tất cả chúng ta đều đâm đầu vào chỗ chết."
L2_1.m_Talk_VTN = L3_1
L3_1 = "这种情况下你又要干什么？都快死了，哪还有人做噩梦啊！"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Das schon wieder?! Niemand wird einen Albtraum haben, wenn wir kurz davor stehen, in den Tod zu stürzen!"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Quoi, encore ce truc ?! On va tous crever là, c'est pas le moment de s'occuper des cauchemars !"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "NEVERLAND_ACT3_INTERLUDE4@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4600313
L3_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L3_1.m_Pos = "R"
L4_1 = "하지만 이 함선이 떨어지면 더 많은 사람들에게 악몽이 스며들 거야."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "でもこの艦船が墜落すればもっと多くの人に悪夢が染み入ることになるよ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "But if this ship falls, the nightmare will spread to more people."
L3_1.m_Talk_ENG = L4_1
L4_1 = "萬一艦船迫降的話，惡夢會擴散至更多人的！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แต่ถ้ายานลำนี้ตก ฝันร้ายจะกระจายไปหาคนมากกว่านี้นะคะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Nhưng nếu con tàu này đâm xuống, cơn ác mộng sẽ lan tràn sang nhiều người hơn."
L3_1.m_Talk_VTN = L4_1
L4_1 = "可是如果这艘舰船坠落了，就会有更多的人做噩梦。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Aber wenn dieses Schiff abstürzt, wird der Albtraum noch viel mehr Menschen infiltrieren."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Mais si vaisseau s'écrase, un terrible cauchemar risque de se propager chez tout le monde."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "NEVERLAND_ACT3_INTERLUDE4@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 4600313
L4_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_DESPAIR"
L4_1.m_CharStrID = "NEWCOMER_NPC_DREAM_NULL"
L4_1.m_Pos = "L"
L5_1 = "그래서? 네가 시그마를 돕는다고 추락을 막을 수 있을 거 같아?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "それで？　アンタがシグマを手伝うとして、墜落を止められるとでも思ってる？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "So? How are you gonna help Sigma stop it from crashing?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "所以呢？你覺得你可以阻止迫降嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แล้วไงล่ะ? เธอจะไปช่วยซิกมาทำไม่ให้มันตกได้ยังไง?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Vậy? Nhóc định giúp Sigma ngăn chặn con tàu bị đâm xuống như thế nào?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "所以呢？你又能怎么帮助西格玛？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Also? Wie willst du denn Sigma dabei helfen, den Absturz zu verhindern?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Et donc quoi ? Tu crois que tu peux aider Sigma ?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "NEVERLAND_ACT3_INTERLUDE4@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 4600313
L5_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_SERIOUS"
L5_1.m_CharStrID = "NEWCOMER_NPC_DREAM_NULL"
L5_1.m_Pos = "L"
L5_1.m_Crash = 20
L6_1 = "자! 말도 안 되는 소리 하지 말고 얼른!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ほら！　バカ言ってないで早く！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "See? Don’t be absurd, and hurry up!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "快點！不要再說那些莫名其妙的話，快過來！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เห็นมั้ย? อย่ามัวเหลวไหลแล้วก็รีบๆ เข้าน่า!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Thấy chưa? Đừng ngớ ngẩn, và nhanh lên!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "好了！别胡说八道了，快点走！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Hey! Red keinen Unsinn und beeil dich lieber!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Arrête de dire des bêtises et dépêche-toi de venir avec nous !"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "NEVERLAND_ACT3_INTERLUDE4@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 4600313
L6_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_SERIOUS"
L6_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L6_1.m_Pos = "R"
L7_1 = "할 수 있어. 시그마와 힘을 합치면."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "できるよ。シグマと力を合わせれば。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "We can stop it. Sigma and I, together."
L6_1.m_Talk_ENG = L7_1
L7_1 = "可以的，只要我和西格瑪的力量加在一起。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เราหยุดมันได้ค่ะ ถ้าฉันกับซิกมาช่วยกัน"
L6_1.m_Talk_THA = L7_1
L7_1 = "Chúng tôi có thể dừng nó. Sigma và tôi, cùng nhau."
L6_1.m_Talk_VTN = L7_1
L7_1 = "可以的。我和西格玛合作的话。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Wir können es aufhalten. Sigma und ich zusammen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Ensemble, nous pouvons l'arrêter. Sigma et moi."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "NEVERLAND_ACT3_INTERLUDE4@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4600313
L7_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_SURPRISE"
L7_1.m_CharStrID = "NEWCOMER_NPC_DREAM_NULL"
L7_1.m_Pos = "L"
L8_1 = "……할 수 있다니? 방금 내가 제대로 들은 거 맞아?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "……できるって？　聞き間違いじゃないよね？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Stop it...? Did I hear that right?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "……可以什麼啦？我剛有聽錯嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "หยุดมันเหรอ...? ฉันหูฝาดรึเปล่าเนี่ย?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Dừng nó...? Tôi có nghe đúng không vậy?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "……可以？我没听错吧？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "... Ihr könnt es aufhalten? Habe ich das gerade richtig gehört?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "... L'arrêter ? J'ai bien entendu ?"
L7_1.m_Talk_FRA = L8_1
