L10_1 = "NEVERLAND_ACT3_INTERLUDE4@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4600313
L9_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_DESPAIR"
L9_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "너는 한결 같은 사람이야. 가시를 세우지만 마음씨는 상냥해."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "グリンダはいつも変わらないね。ツンツンしてても心は優しい。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "You're the same as always, Glinda. Your claws are always out, but you have a kind heart."
L9_1.m_Talk_ENG = L10_1
L10_1 = "你是個表裡如一的人，雖然帶刺心地卻很善良。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "คุณไม่เปลี่ยนเลยนะคะกลินดา แยกเขี้ยวกางเล็บตลอด แต่จริงๆ แล้วจิตใจดี"
L9_1.m_Talk_THA = L10_1
L10_1 = "Glinda vẫn như mọi khi. Khẩu xà nhưng tâm phật."
L9_1.m_Talk_VTN = L10_1
L10_1 = "你总是这样。看似不好相处，但其实心地善良。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Du bist dieselbe wie immer, Glinda. Deine Krallen sind zwar ausgefahren, aber du hast ein gütiges Herz."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Tu n'as pas changée, Glinda. Malgré ton agressivité, tu as un grand cœur."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "NEVERLAND_ACT3_INTERLUDE4@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4600313
L10_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_IDLE"
L10_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L10_1.m_Pos = "C"
L11_1 = "그래서 고마웠어."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "だからありがたく思ってたの。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I've always been grateful for that."
L10_1.m_Talk_ENG = L11_1
L11_1 = "我很感謝你。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ซึ่งฉันซาบซึ้งเรื่องนั้นเสมอนะคะ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi luôn biết ơn vì điều đó."
L10_1.m_Talk_VTN = L11_1
L11_1 = "所以我想要谢谢你，格琳达。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ich bin dir dankbar für alles."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Merci pour tout."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "NEVERLAND_ACT3_INTERLUDE4@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4600313
L11_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L11_1.m_Pos = "C"
L12_1 = "누군가가 자신보다 나를 더 아껴준다는 거, 처음 느껴봤거든."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "誰かが自身より私をもっと大事に思ってくれるのって、初めてのことだったから。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "It was the first time I saw someone who cared about me more than they did about themselves."
L11_1.m_Talk_ENG = L12_1
L12_1 = "你讓我第一次感受到，有人比我更在乎我自己。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เป็นครั้งแรกเลย ที่ฉันเจอคนที่ใส่ใจฉันมากกว่าตัวเอง"
L11_1.m_Talk_THA = L12_1
L12_1 = "Đó là lần đầu tiên tôi thấy một người quan tâm đến tôi hơn chính bản thân họ."
L11_1.m_Talk_VTN = L12_1
L12_1 = "我第一次感受到了，有人比我自己更疼爱我。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Es war das erste Mal, dass ich jemanden getroffen habe, der sich mehr um mich gesorgt hat als um sich selbst."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Tu es quelqu'un de bien, Glinda. Tu te soucies des autres plus que de toi-même."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
