L14_1 = "NEVERLAND_ACT3_INTERLUDE4@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 4600313
L13_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_IDLE"
L13_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "나는 항상 악몽이었어, 글린다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "私はいつも悪夢だったよ、グリンダ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I've always been the nightmare, Glinda."
L13_1.m_Talk_ENG = L14_1
L14_1 = "格琳達，我原是惡夢。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฉันอาจจะเป็นฝันร้ายมาตลอดนะคะกลินดา"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi vẫn luôn là ác mộng, Glinda."
L13_1.m_Talk_VTN = L14_1
L14_1 = "我一直都是噩梦，格琳达。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich war schon immer ein Albtraum, Glinda."
L13_1.m_Talk_DEU = L14_1
L14_1 = "J'ai toujours été un cauchemar, Glinda."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "NEVERLAND_ACT3_INTERLUDE4@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 4600313
L14_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "UNIT_LAUGH"
L14_1.m_Face = L15_1
L14_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L14_1.m_Pos = "C"
L15_1 = "하지만 너에게만큼은, 상쾌한 아침을 맞이해 주는 꿈으로 남을래."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "でもあなたにとってだけは、爽やかな朝を迎えさせてあげられる夢でありたい。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "But I want to remain a dream to you, warm like the morning sun."
L14_1.m_Talk_ENG = L15_1
L15_1 = "但至少面對你，我希望是迎接美好早晨的夢。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "แต่ฉันอยากเหลือความฝันหนึ่งไว้ให้คุณค่ะ ฝันที่อบอุ่นเหมือนพระอาทิตย์ยามเช้า"
L14_1.m_Talk_THA = L15_1
L15_1 = "Nhưng tôi muốn mãi là một giấc mơ với cậu, ấm áp như ánh nắng mai."
L14_1.m_Talk_VTN = L15_1
L15_1 = "但至少对你，我想成为迎接愉快早晨的好梦。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Aber ich möchte für dich ein Traum bleiben, der so warm wie die Morgensonne ist."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Mais toi, je veux que tu te souviennes de moi comme d'un rêve. Comme le rayon de soleil du matin."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
