L18_1 = "<color=#ffd34c>저리 비켜! 내가 먼저 탈 거야!</color>"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "<color=#ffd34c>邪魔するな！　私が先だ！</color>"
L17_1.m_Talk_JPN = L18_1
L18_1 = "<color=#ffd34c>Out of my way! I'm getting on first!</color>"
L17_1.m_Talk_ENG = L18_1
L18_1 = "<color=#ffd34c>給我走開！我要先搭！</color>"
L17_1.m_Talk_TWN = L18_1
L18_1 = "<color=#ffd34c>หลีกไปนะ! ฉันจะขึ้นก่อน!</color>"
L17_1.m_Talk_THA = L18_1
L18_1 = "<color=#ffd34c>Tránh đường! Tôi sẽ đi trước!</color>"
L17_1.m_Talk_VTN = L18_1
L18_1 = "<color=#ffd34c>让开！我要先上船！</color>"
L17_1.m_Talk_SCN = L18_1
L18_1 = "<color=#ffd34c>Aus meinem Weg! Ich steige zuerst ein!</color>"
L17_1.m_Talk_DEU = L18_1
L18_1 = "<color=#ffd34c>Poussez-vous, laissez-moi monter !</color>"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "NEVERLAND_ACT3_INTERLUDE4@118#Talk"
