L19_1 = "<color=#ffd34c>사람 살려!! 이런 데서 죽기 싫어!</color>"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "<color=#ffd34c>助けて！！　こんなところで死にたくない！</color>"
L18_1.m_Talk_JPN = L19_1
L19_1 = "<color=#ffd34c>Somebody, please!! I don't wanna die like this!</color>"
L18_1.m_Talk_ENG = L19_1
L19_1 = "<color=#ffd34c>救命啊！！我不想死在這裡！</color>"
L18_1.m_Talk_TWN = L19_1
L19_1 = "<color=#ffd34c>ใครก็ได้ ขอร้องล่ะ!! ฉันไม่อยากตายแบบนี้!</color>"
L18_1.m_Talk_THA = L19_1
L19_1 = "<color=#ffd34c>Ai đó, làm ơn đi mà!! Tôi không muốn chết như thế này!</color>"
L18_1.m_Talk_VTN = L19_1
L19_1 = "<color=#ffd34c>救命啊！！我不想死在这里！</color>"
L18_1.m_Talk_SCN = L19_1
L19_1 = "<color=#ffd34c>Hilfe!! Ich will nicht so sterben!</color>"
L18_1.m_Talk_DEU = L19_1
L19_1 = "<color=#ffd34c>Non, à l'aide ! Je veux pas mourir comme ça... !</color>"
L18_1.m_Talk_FRA = L19_1
