L35_1 = "Etwas Großes und Flauschiges ist aufgetaucht!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Une énorme boule de fourrure vient de surgir de nulle part dans le ciel !"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "NEVERLAND_ACT3_INTERLUDE4@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
