L36_1 = "UNIT_LAUGH"
L35_1.m_Face = L36_1
L35_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L35_1.m_Pos = "L"
L35_1.m_bCharPinup = true
L35_1.m_bCharPinupEasingTime = 0.25
L36_1 = "우와아! 엄청 커다란 양이다! 털이 푹신푹신해!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "うわあ！　めっちゃ大きな羊さんだ！　毛がふわふわ！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Woooow! It's a giant sheep! The wool is so soft and fluffy!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "哇喔！超大隻的羊欸！毛好軟喔！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "โหวววว! แกะยักษ์นี่นา! ขนนุ่มนิ่มปุกปุยชะมัดเลย!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tuyệt vời! Đó là một con cừu khổng lồ! Len rất mềm và mịn!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "哇啊啊！好大的羊啊！毛软乎乎的！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Woooow! Es ist ein riesiges Schaf! Die Wolle ist so weich und flauschig!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Ouah !! Un mouton géant ? Sa laine est si douce et si moelleuse !"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NEVERLAND_ACT3_INTERLUDE4@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 4600313
L36_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L36_1.m_Pos = "L"
L36_1.m_bCharPinup = true
L37_1 = "태워 줘서 고마워, 양아! 그런데 넌 어디서 왔어?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "乗せてくれてありがとう、羊さん！　でもあなたはどこから来たの？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Thanks for the ride, sheep buddy! But where did you come from?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "羊羊，謝謝你載我！不過你是從哪來的？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ขอบคุณที่ให้ขี่หลังนะคุณแกะ! แต่เธอมาจากไหนน่ะ?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Cảm ơn vì chuyến đi, bạn cừu! Nhưng bạn đến từ đâu?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "谢谢你背着我，羊儿！不过你是从哪儿来的？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Danke für die Fahrt, Schäfchen! Aber wo bist du denn hergekommen?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Merci pour la balade, mouton ! Mais d'où tu viens comme ça ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NEVERLAND_ACT3_INTERLUDE4@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 4600313
L37_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "UNIT_LAUGH"
L37_1.m_Face = L38_1
L37_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L37_1.m_Pos = "R"
L37_1.m_bCharPinup = true
L37_1.m_bCharPinupEasingTime = 0.25
L38_1 = "후후, 칭찬해 줘서 고마워. 시그마."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ふふ、褒めてくれてありがとう。シグマ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Hu hu, thanks for the compliment, Sigma."
L37_1.m_Talk_ENG = L38_1
L38_1 = "呵呵，謝謝你的讚美，西格瑪。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "หึหึ ขอบคุณที่ชมนะ ซิกมา"
L37_1.m_Talk_THA = L38_1
L38_1 = "Hi hi, cám ơn vì lời khen nhé, Sigma."
L37_1.m_Talk_VTN = L38_1
L38_1 = "唔，多谢夸奖，西格玛。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Haha, danke für das Kompliment, Sigma."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Hu hu. Merci pour le compliment, Sigma."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "NEVERLAND_ACT3_INTERLUDE4@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 4600313
L38_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_SURPRISE"
L38_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L38_1.m_Pos = "L"
L38_1.m_bCharPinup = true
L39_1 = "루루? 방금 그 목소리, 루루 맞지?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ルル？　今の声、ルルだよね？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Lulu? That voice... It’s you isn’t it?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "露露？剛剛的聲音是露露對吧？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ลูลู? เสียงนั่น... เธอไม่ใช่เหรอ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Lulu? Giọng nói đó... Là cậu phải không?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "露露？刚才的声音，是露露没错吧？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Lulu? Diese Stimme ... Bist du es?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Lulu ? Cette voix... c'est toi, n'est-ce pas ?"
L38_1.m_Talk_FRA = L39_1
