L39_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L39_1.m_Pos = "R"
L39_1.m_bCharPinup = true
L40_1 = "응. 지금 이 모습이 본래의 나야."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "うん。今のこの姿が本当の私なの。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Yes. This is my original form."
L39_1.m_Talk_ENG = L40_1
L40_1 = "嗯，這才是我原本的樣子。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ใช่ จริงๆ นี่ร่างจริงฉันน่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Đúng. Đây là bản thể của tôi."
L39_1.m_Talk_VTN = L40_1
L40_1 = "嗯，现在就是我本来的样子。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ja. Dies ist meine ursprüngliche Form."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Oui. C'est ma véritable forme."
L39_1.m_Talk_FRA = L40_1
