L41_1 = "NEVERLAND_ACT3_INTERLUDE4@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 4600313
L40_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_DESPAIR"
L40_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L40_1.m_Pos = "R"
L40_1.m_bCharPinup = true
L41_1 = "무척 무거운 함선이네. 오래 버티긴 힘들겠어. "
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "とても重い艦船だね。長くは持たないかも。 "
L40_1.m_Talk_JPN = L41_1
L41_1 = "This ship is really heavy. I don't think I'll be able to stop it for very long. "
L40_1.m_Talk_ENG = L41_1
L41_1 = "這艘艦船好重喔，撐那麼久很辛苦吧。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ยานลำนี้หนักจริงๆ เลย ฉันว่าฉันคงหยุดไว้ได้ไม่นานหรอก "
L40_1.m_Talk_THA = L41_1
L41_1 = "Con tàu này thực sự rất nặng. Tôi không nghĩ mình có thể dừng nó lâu đâu. "
L40_1.m_Talk_VTN = L41_1
L41_1 = "这艘舰船非常重。很难坚持很久。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Dieses Schiff ist wirklich schwer. Ich glaube nicht, dass ich es sehr lange aufhalten kann."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Ce vaisseau est vraiment lourd. Je ne pourrai pas le retenir très longtemps."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "NEVERLAND_ACT3_INTERLUDE4@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 4600313
L41_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_IDLE"
L41_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L41_1.m_Pos = "R"
L41_1.m_bCharPinup = true
L42_1 = "도와 주러 왔어. 혼자서 힘내고 있었다니, 정말 대견하다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "助けに来たよ。一人で頑張ってたなんて、本当に偉いね。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I came to help. I'm amazed you were able to slow this thing down all by yourself."
L41_1.m_Talk_ENG = L42_1
L42_1 = "我是來幫你的，你好厲害，可以自己堅持那麼久。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ฉันมาช่วยแล้วนะ ฉันตกใจมากเลยว่าเธอหยุดยานนี่เองคนเดียวได้"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi đến để giúp đỡ. Tôi rất ngạc nhiên vì chỉ mình cậu đã có thể làm chậm thứ này lại."
L41_1.m_Talk_VTN = L42_1
L42_1 = "我是来帮你的，你一个人在努力，真的很了不起。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich bin gekommen, um zu helfen. Ich bin erstaunt, dass du es geschafft hast, dieses Schiff ganz alleine zu entschleunigen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Je suis venue t'aider. Ça n'a pas dû être facile de soutenir cette chose toute seule pendant aussi longtemps."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "NEVERLAND_ACT3_INTERLUDE4@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 4600313
L42_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_DESPAIR"
L42_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L42_1.m_Pos = "L"
L42_1.m_bCharPinup = true
L43_1 = "그치만 이제 곧 한계야. 에너지가 다 떨어졌어."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "でももうすぐ限界なの。エネルギーが尽きちゃった。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "But I'm reaching my limit. I'm all out on energy."
L42_1.m_Talk_ENG = L43_1
L43_1 = "可是我差不多到極限了，能源都用光了。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "แต่ก็สุดแรงแล้วล่ะ พลังงานฉันหมดเกลี้ยงแล้ว"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nhưng tôi đang đạt đến giới hạn của mình. Tôi cạn kiệt năng lượng rồi."
L42_1.m_Talk_VTN = L43_1
L43_1 = "可是我就要到极限了。能量都用完了。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Aber ich komme an meine Grenzen. Ich habe fast meine gesamte Energie aufgebraucht."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oui, j'ai atteint ma limite. Mes batteries sont à plat."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
