L44_1.m_bCharPinupEasingTime = 0.25
L45_1 = "앗! 저 소리, 함선 쪽에서 났어!?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "あっ！　あの音、艦船の方からじゃない！？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Huh?! Did that explosion come from the ship?!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "唔！那個聲音，是從艦船裡傳出來的嗎！？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "หือ?! ระเบิดนั่นมาจากยานเหรอ?!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Hử?! Có phải vụ nổ phát ra từ con tàu không?!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "啊！那个声音，是从舰船那边传来的！？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Huch?! Kam diese Explosion vom Schiff?!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Ah ! Une explosion ? Ça venait du vaisseau... !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "NEVERLAND_ACT3_INTERLUDE4@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 4600313
L45_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_SERIOUS"
L45_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L45_1.m_Pos = "C"
L45_1.m_bCharPinup = true
L45_1.m_bCharPinupEasingTime = 0.25
L46_1 = "함선이 무너지려고 해. 동력을 잃어서 무게를 견디지 못하나 봐."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "艦船が崩れようとしてるの。動力を失って、重さに耐えられなくなったみたい。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "The ship's lost its power and can't withstand the weight. It's going to fall."
L45_1.m_Talk_ENG = L46_1
L46_1 = "艦船要塌了，因為失去動能，無法支撐重量的樣子。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ยานเสียพลังงานจนแบกน้ำหนักตัวเองไม่ไหวน่ะ มันกำลังจะตกแล้ว"
L45_1.m_Talk_THA = L46_1
L46_1 = "Con tàu đã bị mất năng lượng và không thể chịu được trọng lượng. Nó sắp đâm xuống rồi."
L45_1.m_Talk_VTN = L46_1
L46_1 = "舰船要解体了。好像是失去动力之后，无法承受各部分的重量了。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Das Schiff hat seine Antriebskraft verloren und kann dem Gewicht nicht standhalten. Es wird abstürzen."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Le vaisseau va s'écraser d'une minute à l'autre. Maintenant que les moteurs sont arrêtés, il n'y a plus rien pour ralentir sa chute."
L45_1.m_Talk_FRA = L46_1
