L49_1 = "NEVERLAND_ACT3_INTERLUDE4@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 4600313
L48_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_DESPAIR"
L48_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L48_1.m_Pos = "L"
L48_1.m_bCharPinup = true
L48_1.m_bCharPinupEasingTime = 0.25
L49_1 = "그럼 안 돼! 안에 타고 있는 사람들도, 도시 사람들도 전부……!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ダメ！　中に乗ってる人たちも、都市の人たちも全部……！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "No! There are people on that ship, and even more down below...!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "不可以！那艦船裡的人，和城裡的人全部都會……！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ไม่ได้นะ! มีผู้โดยสารอยู่บนยาน แถมข้างล่างก็มีอีกเยอะกว่ามากเลย!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Không! Có người trên con tàu đó, và còn nhiều người hơn ở bên dưới...!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "那可不行！里面有很多人，城里也全都是人……！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Nein, das darf nicht passieren! Auf diesem Schiff befinden sich so viele Menschen und unten uns sogar noch mehr ...!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Non ! Il y a encore des passagers ! Et en dessous, tous ces gens vont... !"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "NEVERLAND_ACT3_INTERLUDE4@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 4600313
L49_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L49_1.m_Pos = "R"
L49_1.m_bCharPinup = true
L50_1 = "차분하게 생각해, 시그마. 네가 지닌 힘을 잊지 마."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "落ち着いて考えて、シグマ。あなたの力を忘れないで。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Stay calm and think, Sigma. Don't forget about your strength."
L49_1.m_Talk_ENG = L50_1
L50_1 = "西格瑪，冷靜點，不要忘記你擁有的力量。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ใจเย็นแล้วค่อยๆ คิดนะซิกมา อย่าลืมจุดแข็งของตัวเองสิ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Hãy bình tĩnh và suy nghĩ đi nào, Sigma. Đừng quên sức mạnh của cậu."
L49_1.m_Talk_VTN = L50_1
L50_1 = "冷静点，西格玛。别忘了你拥有的力量。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Bleib ruhig und denk nach, Sigma. Vergiss deine Kräfte nicht."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Garde ton calme et réfléchis, Sigma. Pense à ton pouvoir..."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
