L2_1 = "NEVERLAND_ACT3_INTERLUDE4@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 4600313
L1_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L1_1.m_bWaitClick = true
