L1_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L1_1.m_Pos = "L"
L1_1.m_bCharPinup = true
L2_1 = "하지만 에너지가 부족해. 이것만 가지고는 할 수 없어."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "でもエネルギーが足りないよ。これだけじゃできないんだ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "But I don’t have enough power. I can’t do it with this little."
L1_1.m_Talk_ENG = L2_1
L2_1 = "可是能源不足也派不上用場。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แต่ฉันมีพลังงานไม่พอนี่นา มีแค่นี้ไม่ไหวหรอก"
L1_1.m_Talk_THA = L2_1
L2_1 = "Nhưng tôi không còn đủ sức mạnh nữa. Tôi không thể làm điều đó với phần sức mạnh nhỏ nhoi này."
L1_1.m_Talk_VTN = L2_1
L2_1 = "可是我的能量快耗光了，光靠现在这些做不到。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Aber ich habe nicht genug Kraft. Ich kann es nicht schaffen."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Mais je n'ai plus d'énergie ! Qu'est-ce que je peux faire ?"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "NEVERLAND_ACT3_INTERLUDE4@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 4600313
L2_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_SURPRISE"
L2_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L2_1.m_Pos = "R"
L2_1.m_bCharPinup = true
L3_1 = "그러니? "
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "そう？ "
L2_1.m_Talk_JPN = L3_1
L3_1 = "What then? "
L2_1.m_Talk_ENG = L3_1
L3_1 = "所以呢？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "งั้นยังไงดีนะ? "
L2_1.m_Talk_THA = L3_1
L3_1 = "Tiếp theo phải làm gì đây? "
L2_1.m_Talk_VTN = L3_1
L3_1 = "是吗？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Also?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Vraiment ?"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "NEVERLAND_ACT3_INTERLUDE4@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4600313
L3_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "UNIT_LAUGH"
L3_1.m_Face = L4_1
L3_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L3_1.m_Pos = "R"
L3_1.m_bCharPinup = true
L4_1 = "그렇다면 다른 사람들에게 물어 보면 어떨까?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "それなら他の人たちに聞いてみればどうかな？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Why don’t we ask other people for help?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "那還是要問問其他人呢？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ทำไมไม่ขอให้คนอื่นช่วยล่ะ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Tại sao chúng ta không nhờ người khác giúp đỡ?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "那问问其他人怎么样？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Warum bitten wir andere Menschen nicht um Hilfe?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Dans ce cas, si tu demandais de l'aide ?"
L3_1.m_Talk_FRA = L4_1
