L7_1 = "NEVERLAND_ACT3_INTERLUDE4@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 4600313
L6_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "퇴근길 위로, 커다란 양 위에 올라탄 밝고 작은 불빛이 함선을 떠받치고 있었다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "m_bTalkCenterFadeIn"
L6_1[L7_1] = true
L7_1 = "退勤後の帰り道、上空に大きな羊の上に乗った明るくて小さな光が艦船を支えていた。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "On my way home, I saw a small light on top of a giant sheep holding up a ship."
L6_1.m_Talk_ENG = L7_1
L7_1 = "下班路上，巨大的羊上方，閃爍的微小火光支撐著艦船。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ระหว่างกลับบ้าน ผมเห็นแสงเล็กๆ เหนือแกะยักษ์ที่แบกยานไว้"
L6_1.m_Talk_THA = L7_1
L7_1 = "Trên đường về nhà, tôi nhìn thấy một ngọn đèn nhỏ trên đầu một con cừu khổng lồ đang níu lấy một con tàu."
L6_1.m_Talk_VTN = L7_1
L7_1 = "下班路上，天空中有一只大羊背着一小簇亮光，摇摇欲坠地支撑着舰船。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Auf dem Heimweg sah ich ein kleines Licht über einem riesigen Schaf, das ein Schiff hochhielt."
L6_1.m_Talk_DEU = L7_1
L7_1 = "En rentrant du travail, j'aperçois une lueur briller dans le ciel nocturne. Un mouton géant qui porte un vaisseau sur son dos."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "NEVERLAND_ACT3_INTERLUDE4@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4600313
L7_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "대피 경보 따위 개나 줘 버려. 도망쳐 봐야 어디까지 가겠어."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "m_bTalkCenterFadeIn"
L7_1[L8_1] = true
L8_1 = "退避警報なんてクソ食らえ。どうせ遠くまでは逃げられない。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Who cares about the sirens? Where am I even supposed to evacuate to?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "避難警報說給狗聽吧，是能逃到哪裡去。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ใครจะไปสนเสียงหวอกันล่ะ? ผมจะอพยพไหนได้ก่อนเหอะ?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ai quan tâm đến những tiếng còi báo động chứ? Tôi thậm chí còn phải đi đâu sơ tán đây?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "避险警报什么的还是给狗听吧。就算逃跑又能逃到哪里去。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Wen kümmern denn schon die Sirenen? Wohin soll ich überhaupt flüchten?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Les sirènes d'évacuation sifflent dans tous les sens, mais à quoi bon ? On se cache un instant, et après ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "NEVERLAND_ACT3_INTERLUDE4@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 4600313
L8_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "그럴 시간에 차라리 저 광경을 좀 더 눈에 담고 싶어."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "m_bTalkCenterFadeIn"
L8_1[L9_1] = true
L9_1 = "その時間にむしろあの光景をもっと見ておきたいんだ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I'd rather spend a little more time looking at what's happening in the sky."
L8_1.m_Talk_ENG = L9_1
L9_1 = "有時間逃，不如再多看幾眼這樣的光景。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ผมอยากใช้เวลาดูว่าเกิดอะไรขึ้นบนฟ้าต่อมากกว่า"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi thà dành thêm chút thời gian để chiêm ngưỡng những gì đang xảy ra trên bầu trời."
L8_1.m_Talk_VTN = L9_1
L9_1 = "有那个时间，我宁愿多看几眼那个场景。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich verbringe lieber etwas mehr Zeit damit, zu beobachten, was am Himmel passiert."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Je préfère passer un peu plus de temps à regarder ce qui se passe dans le ciel."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "NEVERLAND_ACT3_INTERLUDE4@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4600313
L9_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "힘에 부친다는 게 느껴져. 불빛이 희미해져 가고 있어."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "m_bTalkCenterFadeIn"
L9_1[L10_1] = true
L10_1 = "力が及ばないということがわかる。光りがどんどん弱くなっていく。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I feel it being overpowered, and the light gets dimmer."
L9_1.m_Talk_ENG = L10_1
L10_1 = "似乎有點吃力，火光越來越微弱。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ผมรู้สึกว่ามันสู้ไม่ไหวแล้ว และแสงนั่นก็เริ่มอ่อนลง"
L9_1.m_Talk_THA = L10_1
L10_1 = "Tôi cảm thấy nó bị áp đảo, và ánh đèn trở nên mờ dần."
L9_1.m_Talk_VTN = L10_1
L10_1 = "能感觉到她的力不从心，亮光越来越微弱了。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ich habe das Gefühl, dass ich überwältigt bin. Das Licht wird schwächer."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Ce mouton semble à bout de forces. La lumière faiblit à vue d'œil."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "NEVERLAND_ACT3_INTERLUDE4@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4600313
L10_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "하지만…… 사는 대로 사는 내가 말하긴 부끄럽지만."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "m_bTalkCenterFadeIn"
L10_1[L11_1] = true
L11_1 = "でも……適当に生きている僕がこんなことを話すのは恥ずかしいけど。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "And even though I'm a little embarrassed to say this as I just go with the flow in life..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "不過……雖然得過且過的我這麼說有點羞愧，"
L10_1.m_Talk_TWN = L11_1
L11_1 = "และถึงจะอายนิดๆ ที่จะพูดอย่างนี้ก็เถอะ เพราะผมใช้ชีวิตแบบตามบุญตามกรรมมาตลอด...."
L10_1.m_Talk_THA = L11_1
L11_1 = "Và mặc dù tôi hơi xấu hổ khi nói điều này khi cứ xuôi theo dòng chảy của cuộc sống..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "虽然……有些话从每天混日子的我嘴里说出来，有点不好意思。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Und obwohl es mir ein wenig peinlich ist, das zu sagen, weil ich einfach mit dem Strom des Lebens schwimme ..."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Ça me va bien de dire ça, moi qui ai abandonné tout espoir, mais..."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "NEVERLAND_ACT3_INTERLUDE4@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4600313
L11_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "조금만 더, 아주 조금만 더 힘을 내 줘."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "m_bTalkCenterFadeIn"
L11_1[L12_1] = true
L12_1 = "もう少しだけ、もう少しだけ頑張って。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Hang in there just a little longer! I'm rooting for you!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "但撐一下，再撐一下就好。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "แต่อดทนอีกนิดนะ! ผมเอาใจช่วยอยู่!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Cố gắng trụ lại lâu hơn chút nữa đi! Tôi cổ vũ cho bạn!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "不过——“一定要再加把劲啊！再加把劲儿！”"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Halt noch ein bisschen länger durch! Ich drück dir die Daumen!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "« Allez, tiens bon encore un peu ! Tu vas y arriver ! »"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
