L15_1 = "NEVERLAND_ACT3_INTERLUDE4@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 4600313
L14_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L15_1 = "안녕! 난 시그마! 아빠 딸이야!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "こんにちは！　私はシグマ！　パパの娘だよ！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Hi! I'm Sigma! Daddy's girl!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "哈囉！我是西格瑪！是爸爸的女兒！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "หวัดดีค่ะ! นี่ซิกมานะคะ! ลูกสาวคุณพ่อ!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Xin chào! Tôi là Sigma! Con gái của bố!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "大家好！我叫西格玛！是爸爸的女儿！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Hallo! Ich heiße Sigma. Ich bin Papas Tochter!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Salut ! Je suis Sigma. La fille de papa !"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "NEVERLAND_ACT3_INTERLUDE4@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4600313
L15_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "핸드폰에서 밝은 목소리가 들려왔다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "m_bTalkCenterFadeIn"
L15_1[L16_1] = true
L16_1 = "ケータイから明るい声が聞こえてきた。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I hear a bright voice coming from my phone."
L15_1.m_Talk_ENG = L16_1
L16_1 = "手機傳來一個爽朗的聲音。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "มีเสียงแจ๋วดังออกมาจากโทรศัพท์แฮะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tôi nghe thấy một giọng nói tươi sáng phát ra từ điện thoại của tôi."
L15_1.m_Talk_VTN = L16_1
L16_1 = "手机里传来了明快的声音。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ich höre eine lebhafte Stimme aus meinem Handy."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Une voix clair surgit subitement de mon téléphone."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "NEVERLAND_ACT3_INTERLUDE4@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4600313
L16_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L17_1 = "미안해. 도시로 떨어지는 함선을 세우려고 했는데, 나랑 친구만으로는 힘이 부족해."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ごめんね。都市に落ちかかってる艦船を止めようとしたけど、私と友達の力だけでは足りないの。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "I’m sorry. My friend and I tried to stop the ship from falling on this city, but we aren't strong enough."
L16_1.m_Talk_ENG = L17_1
L17_1 = "不好意思，我想阻止艦船掉到城市裡，但光靠我和朋友的力量不太夠。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ขอโทษด้วยนะคะ พอดีเพื่อนหนูกำลังพยายามหยุดไม่ให้ยานตกใส่เมืองนี้น่ะค่ะ แต่เราแข็งแรงไม่พอ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi xin lỗi. Bạn tôi và tôi đã cố gắng ngăn con tàu rơi xuống thành phố này, nhưng chúng tôi không đủ sức."
L16_1.m_Talk_VTN = L17_1
L17_1 = "对不起，我想停下正在掉进城市里的舰船，但光靠我和朋友，力量还不够。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Es tut mir leid. Meine Freundin und ich haben versucht, den Absturz des Schiffes auf diese Stadt zu verhindern, aber wir waren nicht stark genug."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Je suis désolée. Mon amie et moi avons tout fait pour empêcher le vaisseau de s'écraser, mais nous ne sommes pas assez fortes."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "NEVERLAND_ACT3_INTERLUDE4@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4600313
L17_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L18_1 = "그래서 도시의 전력을 잠깐만 빌리려고 해."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "それで、都市の電力をちょっと借りようと思うんだ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "So we're thinking of borrowing the city's power for just a moment."
L17_1.m_Talk_ENG = L18_1
L18_1 = "所以想借用一下這個城市的電。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ก็เลยคิดว่าจะขอยืมพลังของเมืองสักครู่น่ะค่ะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Vì vậy, chúng tôi đang nghĩ đến việc mượn sức mạnh của thành phố trong giây lát."
L17_1.m_Talk_VTN = L18_1
L18_1 = "所以我想借用一下城市里的电力！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Deshalb denken wir darüber nach, vorrübergehend die Kraft der Stadt zu nutzen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Alors j'ai besoin de votre aide. J'aimerais emprunter le courant de la ville un instant."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
