L21_1 = "UNIT_PRIDE"
L20_1.m_Face = L21_1
L20_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L20_1.m_Pos = "C"
L20_1.m_bCharHologramEffect = true
L20_1.m_Crash = 15
L21_1 = "잠깐이면 되니까! 응?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "ちょっとでいいから！　ね？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "It won't take long! So please let us borrow it?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "借一下就好！可以嗎？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ไม่นานหรอกนะคะ! เพราะงั้น ขอเรายืมได้มั้ยคะ?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Sẽ không kéo dài lâu đâu! Vậy nên làm ơn cho chúng tôi mượn chút được không?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "一会儿就好！可以吗？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Es wird nicht lange dauern! Dürfen wir sie kurz nutzen?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Ça ne sera pas long, j'espère que vous comprendrez !"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
