L23_1 = "NEVERLAND_ACT3_INTERLUDE4@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 4600313
L22_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "화면에 떠오른 것은 승낙과 거절의 뜻을 지닌 두 개의 단추."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "m_bTalkCenterFadeIn"
L22_1[L23_1] = true
L23_1 = "画面に浮かんだのは承諾と拒否の意味を持っている二つのボタン。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Two buttons appear on my screen, one to accept and one to decline."
L22_1.m_Talk_ENG = L23_1
L23_1 = "畫面上出現二個按鈕，一個是同意，一個是拒絕。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "บนหน้าจอมีขึ้นมาสองปุ่ม ปุ่มนึงยอมรับ อีกปุ่มปฏิเสธ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Hai nút xuất hiện trên màn hình của tôi, một để chấp nhận và một để từ chối."
L22_1.m_Talk_VTN = L23_1
L23_1 = "画面上显示的是表示同意和拒绝意思的两个按钮。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Auf meinem Bildschirm erscheinen zwei Knöpfe, einer zum Akzeptieren und einer zum Ablehnen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Deux boutons apparaissent sur mon écran : « Accepter » et « Refuser »."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "NEVERLAND_ACT3_INTERLUDE4@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 4600313
L23_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "무심코 주위를 둘러 보니 다른 운전자들도 핸드폰을 들여다보고 있다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "m_bTalkCenterFadeIn"
L23_1[L24_1] = true
L24_1 = "何気なく周りを見回すと、他のドライバーもみんなケータイを覗き込んでいる。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I look up to see the other drivers, and they're also looking down at their phones."
L23_1.m_Talk_ENG = L24_1
L24_1 = "無意間環顧四周，其他駕駛人也都在看手機。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ผมเงยหน้ามองคนขับรถคนอื่นๆ แต่ทุกคนก็กำลังก้มหน้ามองโทรศัพท์ตัวเองอยู่เหมือนกัน"
L23_1.m_Talk_THA = L24_1
L24_1 = "Tôi nhìn lên để xem các tài xế khác và họ cũng đang nhìn xuống điện thoại của họ."
L23_1.m_Talk_VTN = L24_1
L24_1 = "我下意识地抬头环顾四周，其他司机也都在看手机。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ich erhebe meinen Blick und sehe, dass die anderen Fahrer auch auf ihre Handys schauen."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Je lève les yeux un instant. Tous les conducteurs sont sur leur téléphone, eux aussi."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "NEVERLAND_ACT3_INTERLUDE4@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 4600313
L24_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_DESPAIR"
L24_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L24_1.m_Pos = "C"
L24_1.m_bCharHologramEffect = true
L25_1 = "나는…… 오늘 정말 많은 일을 겪었는걸."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "私……今日は本当にたくさんのことがあったんだ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "A lot of things... happened to me today."
L24_1.m_Talk_ENG = L25_1
L25_1 = "我……今天真的遇到超多事的！"
L24_1.m_Talk_TWN = L25_1
L25_1 = "วันนี้... หนูเจออะไรหลายอย่างเลยค่ะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Rất nhiều thứ... đã xảy ra với tôi hôm nay."
L24_1.m_Talk_VTN = L25_1
L25_1 = "我……今天真的经历了很多事。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Mir ... sind heute viele Dinge widerfahren."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Aujourd'hui... il s'est passé beaucoup de choses."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "NEVERLAND_ACT3_INTERLUDE4@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 4600313
L25_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_SERIOUS"
L25_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L25_1.m_Pos = "C"
L25_1.m_bCharHologramEffect = true
L26_1 = "싫은 일도 있었지만 좋은 일도 있었어! 그래서 내일이, 매일매일이 기대돼!"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "イヤなこともあったけど、いいこともあったんだよ！　だから明日が、毎日が楽しみ！"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Some things made me sad, but others were enjoyable! That's why I look forward to seeing what tomorrow has in store for me every day!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "雖然有討厭的事，但也有開心的事！所以我每一天都很期待！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "บางอย่างก็ทำให้เสียใจ แต่คนอื่นๆ เขาสนุกกัน! ดังนั้นทุกวันหนูก็เลยอยากรู้ว่าพรุ่งนี้จะมีอะไรรออยู่ค่ะ!"
L25_1.m_Talk_THA = L26_1
L26_1 = "Một số điều đã khiến tôi buồn, nhưng những điều khác lại rất thú vị! Đó là lý do tại sao tôi muốn được thấy những thứ có trong cửa hàng mỗi ngày!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "虽然也有讨厌的事，但也有开心的事！所以明天，还有之后的每一天——我都很期待！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Manche Dinge machten mich traurig, andere waren schön! Deshalb kann ich es kaum erwarten, jeden Tag zu sehen, was der morgige Tag für mich bereithält!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Des choses tristes, et d'autres plus joyeuses ! Du coup, j'ai hâte de voir ce que demain nous réserve !"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "NEVERLAND_ACT3_INTERLUDE4@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4600313
L26_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "UNIT_LAUGH"
L26_1.m_Face = L27_1
L26_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L26_1.m_Pos = "C"
L26_1.m_bCharHologramEffect = true
L27_1 = "그 기분을 앞으로도 모두가 알아 주면 좋겠으니까……! 부탁해!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "その気持ちをこれからもみんなにわかってほしいから……！　お願い！"
L26_1.m_Talk_JPN = L27_1
L27_1 = "And I want all of you to feel what I feel... So won’t you please help me?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "我希望大家以後也都能知道這種心情，所以……！拜託！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "แล้วหนูก็อยากให้ทุกคนรู้สึกเหมือนหนูด้วย... แล้วคุณจะไม่ช่วยหนูหน่อยเหรอคะ?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Và tôi muốn tất cả các bạn cảm thấy cảm xúc của tôi... Vì vậy, làm ơn giúp tôi được chứ?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "我希望以后大家也能明白这种心情……！所以拜托大家了！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Und ich möchte, dass ihr alle das fühlt, was ich fühle ... Also könnt ihr mir bitte helfen?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Et vous, vous ne voulez pas voir de quoi demain sera fait ? Alors s'il vous plaît... aidez-moi !"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "NEVERLAND_ACT3_INTERLUDE4@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 4600313
L27_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "나는 다른 모두가 누른 단추를 눌렀다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "m_bTalkCenterFadeIn"
L27_1[L28_1] = true
L28_1 = "僕は他の全員が押したボタンを押した。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I pressed the same button as everyone else."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我和大家都按下相同的按鈕。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ผมกดปุ่มเดียวกับทุกคนไปแล้ว"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tôi đã nhấn nút giống như những người khác."
L27_1.m_Talk_VTN = L28_1
L28_1 = "我按下了其他人也都会按下的按钮。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ich habe den gleichen Knopf gedrückt wie alle anderen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "J'appuie. Sans doute sur le même bouton que tout le monde."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "NEVERLAND_ACT3_INTERLUDE4@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4600313
L28_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "적어도 내일은, 저 아이 덕분에 오늘보다 재밌겠다고 생각하면서."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "m_bTalkCenterFadeIn"
L28_1[L29_1] = true
L29_1 = "少なくとも明日は、あの子のおかげで今日より楽しくなりそうだって思いながら。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Hoping that thanks to that kid, at least tomorrow will be a better day."
L28_1.m_Talk_ENG = L29_1
L29_1 = "至少明天，託她的福可以過得比今天更開心。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "หวังว่าเพราะเด็กคนนั้น อย่างน้อยพรุ่งนี้ก็จะดีกว่าวันนี้นะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Hy vọng rằng nhờ đứa trẻ đó, ít nhất ngày mai sẽ là một ngày tốt đẹp hơn."
L28_1.m_Talk_VTN = L29_1
L29_1 = "我觉得，因为那个孩子，至少明天，会比今天更有意思。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ich hoffe, dass dank dieses Kindes zumindest morgen ein besserer Tag wird."
L28_1.m_Talk_DEU = L29_1
L29_1 = "En espérant que grâce à cet enfant, demain sera un jour meilleur."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
