L30_1 = "m_bTalkCenterFadeIn"
L29_1[L30_1] = true
L30_1 = "<color=#ffd34c>助けてあげるよ。</color>"
L29_1.m_Talk_JPN = L30_1
L30_1 = "<color=#ffd34c>I will help you.</color>"
L29_1.m_Talk_ENG = L30_1
L30_1 = "<color=#ffd34c>我也來幫忙！</color>"
L29_1.m_Talk_TWN = L30_1
L30_1 = "<color=#ffd34c>ผมจะช่วยเธอเอง</color>"
L29_1.m_Talk_THA = L30_1
L30_1 = "<color=#ffd34c>Tôi sẽ giúp.</color>"
L29_1.m_Talk_VTN = L30_1
L30_1 = "<color=#ffd34c>让我帮你吧。</color>"
L29_1.m_Talk_SCN = L30_1
L30_1 = "<color=#ffd34c>Ich werde euch helfen.</color>"
L29_1.m_Talk_DEU = L30_1
L30_1 = "<color=#ffd34c>Je vais t'aider.</color>"
