L38_1.m_Face = "UNIT_SERIOUS"
L38_1.m_CharStrID = "RESORT_NPC_HAVEN_NULL"
L38_1.m_Pos = "C"
L38_1.m_Crash = 20
L39_1 = "이대로는 헤이븐 랜드가 공중 분해될 거야! 뭐라도 꽉 잡아!"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "このままではヘイブンランドが空中分解するよ！　何でもいいから掴んで！"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Havenland's gonna blow to smithereens at this rate! Hold on to something tight!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "這樣下去，天堂樂園會在空中解體的！大家找個東西抓緊！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แบบนี้แฮฟเวนแลนด์ระเบิดเป็นจุณแน่! หาอะไรเกาะไว้ให้แน่นนะ!"
L38_1.m_Talk_THA = L39_1
L39_1 = "Havenland sẽ tan tành nếu cứ với tốc độ này! Hãy níu chặt cái gì đó đi!"
L38_1.m_Talk_VTN = L39_1
L39_1 = "这样下去，海文乐园要解体了！抓好别掉下去了！"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Bei dieser Geschwindigkeit wird Havenland in alle Einzelteile zerschmettert! Haltet euch gut fest!"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Havenland va se désintégrer en plein vol ! Accrochez-vous à ce que vous pouvez !"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "NEVERLAND_ACT3_INTERLUDE4@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 4600313
L39_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
