L40_1.m_Face = "UNIT_HATE"
L40_1.m_CharStrID = "RESORT_NPC_HAVEN_NULL"
L40_1.m_Pos = "C"
L40_1.m_Crash = 15
L41_1 = "무슨 소리야! 정신……!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "何を言ってるんだ！　しっかり……！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "What do you mean, \"no\"?! Get–!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "你在說什麼！你……！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ไอ้ \"ไม่\" ที่ว่านั่นมันยังไงนะ?! หาอะไร–!"
L40_1.m_Talk_THA = L41_1
L41_1 = "Hả???  \"Không\" ư?! Lấy-!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "你在说什么！你疯了吗……！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Wie bitte?! Reiß dich –"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Comment ça, non ? Tu vois pas que─"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
