L44_1 = "NEVERLAND_ACT3_INTERLUDE4@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 4600313
L43_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "<color=#ffd34c>진단. 시그마 프로토콜에 의한 파손 부분 수복 완료. 메인 시스템 재기동.</color>"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "<color=#ffd34c>診断。シグマ・プロトコルによる破損を部分修復完了。メインシステムを再起動。</color>"
L43_1.m_Talk_JPN = L44_1
L44_1 = "<color=#ffd34c>Diagnosing. Partial restoration through Sigma Protocol, complete. Main system reactivated.</color>"
L43_1.m_Talk_ENG = L44_1
L44_1 = "<color=#ffd34c>診斷，西格瑪協定損壞部分已修復完畢，主要系統重新啟動。</color>"
L43_1.m_Talk_TWN = L44_1
L44_1 = "<color=#ffd34c>กำลังวินิจฉัย การฟื้นฟูบางส่วนผ่านซิกมาโปรโตคอล เสร็จสิ้น ระบบหลักกลับมาทำงานแล้ว</color>"
L43_1.m_Talk_THA = L44_1
L44_1 = "<color=#ffd34c>Đang chẩn đoán. Khôi phục một phần thông qua Giao Thức Sigma, hoàn tất. Hệ thống chính đã được kích hoạt lại.</color>"
L43_1.m_Talk_VTN = L44_1
L44_1 = "<color=#ffd34c>诊断结束。依据西格玛协议，损坏部分已修复完毕。主系统将重新启动。</color>"
L43_1.m_Talk_SCN = L44_1
L44_1 = "<color=#ffd34c>Diagnose läuft. Teilweise Wiederherstellung durch das Sigma-Protokoll abgeschlossen. Das Hauptsystem wurde reaktiviert.</color>"
L43_1.m_Talk_DEU = L44_1
L44_1 = "<color=#ffd34c>Diagnostic du protocole Sigma : restauration partielle terminée. Réactivation du système principal.</color>"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "NEVERLAND_ACT3_INTERLUDE4@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 4600313
L44_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "<color=#ffd34c>꿈과 희망의 낙원, 헤이븐 랜드에 오신 승객 여러분을 환영합니다.</color>"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "<color=#ffd34c>夢と希望の楽園、ヘイブンランドへお越しくださった乗客の皆様、ようこそ。</color>"
L44_1.m_Talk_JPN = L45_1
L45_1 = "<color=#ffd34c>Welcome to Havenland! The paradise of your hopes and dreams!</color>"
L44_1.m_Talk_ENG = L45_1
L45_1 = "<color=#ffd34c>歡迎各位乘客來到夢想和希望的天堂樂園。</color>"
L44_1.m_Talk_TWN = L45_1
L45_1 = "<color=#ffd34c>ยินดีต้อนรับสู่แฮฟเวนแลนด์! แดนสวรรค์แห่งความหวังและความฝัน!</color>"
L44_1.m_Talk_THA = L45_1
L45_1 = "<color=#ffd34c>Chào mừng đến với Havenland! Thiên đường của những hy vọng và giấc mơ!</color>"
L44_1.m_Talk_VTN = L45_1
L45_1 = "<color=#ffd34c>欢迎各位乘客来到梦想与希望的乐园——海文乐园。</color>"
L44_1.m_Talk_SCN = L45_1
L45_1 = "<color=#ffd34c>Willkommen im Havenland! Das Paradies Ihrer Hoffnungen und Träume!</color>"
L44_1.m_Talk_DEU = L45_1
L45_1 = "<color=#ffd34c>Bienvenue à Havenland ! Le paradis de vos rêves et espoirs les plus fous !</color>"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "NEVERLAND_ACT3_INTERLUDE4@195#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 4600313
L45_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "<color=#ffd34c>평형 조정 중 약간의 흔들림이 있을 수 있습니다. 조심해 주세요.</color>"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "<color=#ffd34c>平衡調整中、少々揺れることがございます。お気を付けください。</color>"
L45_1.m_Talk_JPN = L46_1
L46_1 = "<color=#ffd34c>There might be some slight turbulence as we stabilize. Please watch your step.</color>"
L45_1.m_Talk_ENG = L46_1
L46_1 = "<color=#ffd34c>船身正在調整平衡，會有點搖晃，請各位乘客小心。</color>"
L45_1.m_Talk_TWN = L46_1
L46_1 = "<color=#ffd34c>ระหว่างกำลังทำให้ทุกอย่างเข้าที่อาจมีความวุ่นวายเกิดขึ้นบ้าง โปรดเดินอย่างระมัดระวังด้วย</color>"
L45_1.m_Talk_THA = L46_1
L46_1 = "<color=#ffd34c>Có thể có một số nhiễu loạn nhỏ khi chúng ta làm thao tác ổn định. Hãy chú ý bước đi.</color>"
L45_1.m_Talk_VTN = L46_1
L46_1 = "<color=#ffd34c>平衡调整过程中可能会有轻微晃动。请大家小心。</color>"
L45_1.m_Talk_SCN = L46_1
L46_1 = "<color=#ffd34c>Während wir uns stabilisieren, kann es zu leichten Turbulenzen kommen. Bitte seien Sie vorsichtig.</color>"
L45_1.m_Talk_DEU = L46_1
L46_1 = "<color=#ffd34c>Nous allons traverser une zone de turbulences. Veuillez regagner votre siège et attacher votre ceinture.</color>"
L45_1.m_Talk_FRA = L46_1
