L49_1.m_Pos = "C"
L49_1.m_Crash = 20
L50_1 = "뭐야, 이거? 왜 추락하지 않는 건데? 왜 박살나지 않는 건데?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "何、これ？　どうして墜落しないの？　どうして粉々にならないのよ？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "What?! Why did it stop falling? Why is it not crashing to the ground?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "怎麼會這樣？為什麼沒有迫降？為什麼沒有解體？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "หา?! ทำไมมันหยุดตกแล้วล่ะ? มำไมมันไม่ตกลงพื้นแล้ว?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Gì thế?! Tại sao nó lại ngừng rơi? Tại sao nó không đâm xuống đất?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "什么啊，这是？为什么不掉下去了？为什么没一起摔个稀巴烂？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Was?! Warum hat es aufgehört, abzustürzen? Warum kracht es nicht mehr zu Boden?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Comment ? Pourquoi on ne s'écrase pas ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
