L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L50_1.m_Crash = 10
L51_1 = "이게 무슨 해피 엔딩만 찾는 동화야……?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "ハッピーエンドしかないおとぎ話でもなし……"
L50_1.m_Talk_JPN = L51_1
L51_1 = "What is this?! Some sort of fairy tale with a happy ending...?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "這是什麼童話般幸福快樂的結局……？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "นี่มันอะไรกัน?! นิทานที่จบอย่างมีความสุขรึไง...?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Cái quái gì vậy?! Chuyện cổ tích kết thúc có hậu à...?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "这是什么美满的童话结局吗……？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Was ist das?! Eine Art Märchen mit Happy End ...?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Qu'est-ce qui s'est passé ? Ne me dites pas qu'on va avoir un happy ending... ?"
L50_1.m_Talk_FRA = L51_1
