L1_1.m_Face = "UNIT_IDLE"
L2_1 = "FX_CUTSCEN_NOISE_RUSTLE_02"
L1_1.m_StartFXSoundName = L2_1
L2_1 = "HAVEN_HAVEN_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "맞아. 동화야, 누나. 오늘만큼은."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "そうだよ。おとぎ話なんだ、姉さん。今日だけはね。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Yup. It's a fairy tale, Sis. At least for tonight."
L1_1.m_Talk_ENG = L2_1
L2_1 = "沒錯，姊姊，就是童話，至少今天是。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ใช่ มันเป็นนิทานครับพี่ อย่างน้อยก็สำหรับคืนนี้"
L1_1.m_Talk_THA = L2_1
L2_1 = "Yup. Đó là một câu chuyện cổ tích, Chị ạ. Ít nhất là vào đêm nay."
L1_1.m_Talk_VTN = L2_1
L2_1 = "没错，是童话，姐姐，至少今天是的。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Jawohl. Es ist ein Märchen, Schwester. Zumindest für heute Abend."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Bingo, sœurette. Tout est bien qui finit bien, au moins ce soir."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "NEVERLAND_ACT3_INTERLUDE4@202#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 202
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 4600313
L2_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "UNIT_PRIDE"
L2_1.m_Face = L3_1
L3_1 = "HAVEN_HAVEN_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "그러니까…… 악당답게 죗값을 치르러 가자."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "だから……悪党らしく罪滅ぼしに行こう。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "So... It's time for the villains to pay."
L2_1.m_Talk_ENG = L3_1
L3_1 = "去吧……付出壞人應付的代價！"
L2_1.m_Talk_TWN = L3_1
L3_1 = "งั้น... ก็ได้เวลาที่วายร้ายต้องชดใช้แล้วนะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Vì vậy... Đã đến lúc kẻ ác phải trả giá."
L2_1.m_Talk_VTN = L3_1
L3_1 = "所以……是时候该为自己的罪行付出代价了。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Also ... es ist Zeit, dass die Bösewichte für ihre Taten büßen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Quant à nous... Il est temps de payer pour nos crimes."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "NEVERLAND_ACT3_INTERLUDE4@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4600313
L3_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "HAVEN_HAVEN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "언제까지나 동화 속에 틀어박혀 살 수는 없잖아."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "いつまでもおとぎ話の中で閉じこもって生きるわけにはいかないからね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "We can't hide inside a fairy tale forever."
L3_1.m_Talk_ENG = L4_1
L4_1 = "總不能一直躲在童話裡吧？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เราจะหลบอยู่ในนิทานไปตลอดกาลไม่ได้หรอก"
L3_1.m_Talk_THA = L4_1
L4_1 = "Chúng ta không thể mãi chờ mong chuyện cổ tích."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我们总不能永远躲在童话故事里。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wir können uns nicht für immer in einem Märchen verstecken."
L3_1.m_Talk_DEU = L4_1
L4_1 = "On ne peut pas vivre cachés dans un conte de fées pour toujours, si ?"
L3_1.m_Talk_FRA = L4_1
