L7_1 = "NEVERLAND_ACT3_INTERLUDE4@206#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 4600313
L6_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "UNIT_LAUGH"
L6_1.m_Face = L7_1
L6_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L6_1.m_Pos = "L"
L6_1.m_bCharPinup = true
L6_1.m_bCharPinupEasingTime = 0.25
L7_1 = "와아! 루루, 우리가 해냈어!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "わあ！　ルル、やったよ！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Wooow! Lulu! We did it!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "哇！露露，我們辦到咧！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "วู้วววว! ลูลู! เราทำสำเร็จแล้ว!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Wooow! Lulu! Chúng ta làm được rồi!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "哇啊！露露，我们做到了！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Wooow! Lulu! Wir haben es geschafft!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Hourra ! Lulu, on a réussi !"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "NEVERLAND_ACT3_INTERLUDE4@207#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4600313
L7_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L7_1.m_Pos = "L"
L7_1.m_bCharPinup = true
L8_1 = "도시 사람들 전부가 힘을 빌려 주니까, 잠깐만 받았을 뿐인데도 든든한 기분이야."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "都市の人たちみんなが力を貸してくれたから、ちょっと電力をもらっただけなのに心強い気分だよ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Even if it was for just a brief moment, I felt reassured when everyone in the city offered me their support."
L7_1.m_Talk_ENG = L8_1
L8_1 = "全城的人都幫我們，雖然只是一下下，卻很給力呢！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ถึงจะแค่แป๊บเดียว แต่ฉันก็อุ่นใจนะที่ทุกคนในเมืองช่วยเหลือน่ะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Dù chỉ trong một khoảnh khắc ngắn ngủi, tôi đã cảm thấy thật an ủi khi mọi người trong thành phố đều sẵn lòng giúp đỡ."
L7_1.m_Talk_VTN = L8_1
L8_1 = "因为城里的人都借给了我力量，虽然很短暂，但我感觉很踏实！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Auch wenn es nur für einen kurzen Moment war, fühlte ich mich beruhigt, als mir alle in der Stadt ihre Unterstützung anboten."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Même si ça n'a pas duré longtemps, je suis heureuse que la ville m'ait apporté son soutien."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "NEVERLAND_ACT3_INTERLUDE4@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 4600313
L8_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "UNIT_LAUGH"
L8_1.m_Face = L9_1
L8_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L8_1.m_Pos = "R"
L8_1.m_bCharPinup = true
L8_1.m_bCharPinupEasingTime = 0.25
L9_1 = "응. 저 거대한 함선을 눈 깜짝할 사이에 원래대로 되돌려 버렸네."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "うん。あの巨大は艦船をあっという間に元どおりに戻しちゃったね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Yes. Even that giant ship got fixed in the blink of an eye."
L8_1.m_Talk_ENG = L9_1
L9_1 = "嗯，眨眼間，那麼大艘的艦船就恢復原樣咧！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ใช่ ยานลำใหญ่ขนาดนั้นยังซ่อมเสร็จในพริบตาเลย"
L8_1.m_Talk_THA = L9_1
L9_1 = "Đúng vậy. Ngay cả con tàu khổng lồ đó cũng được sửa chữa trong nháy mắt."
L8_1.m_Talk_VTN = L9_1
L9_1 = "做得好，那艘巨大的舰船一转眼的功夫就恢复原状了。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ja. Selbst dieses riesige Schiff wurde im Handumdrehen repariert."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Oui. Malgré sa taille, le vaisseau a pu être redressé en un clin d'œil."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "NEVERLAND_ACT3_INTERLUDE4@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4600313
L9_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L9_1.m_Pos = "L"
L9_1.m_bCharPinup = true
L10_1 = "히히, 도시에 있는 사람들에게는 어떻게 고맙다고 전해 줄까?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "へへ、都市にいる人たちにどうやってありがとうって伝えようかな？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Hehe. How do you think I should thank them?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "嘻嘻，該怎麼向城市裡的人表達感謝呢？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฮี่ฮี่! เธอว่าฉันขอบคุณพวกเขายังไงดีอะ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Hi hi! Cậu nghĩ tôi nên cảm ơn họ thế nào cho phải đây?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "嘻嘻，该怎么向城里的人们表达谢意呢？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Hihi. Wie sollte ich ihnen deiner Meinung nach danken?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Hi hi ! Comment tu crois qu'on devrait remercier tous ces gens de la ville ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "NEVERLAND_ACT3_INTERLUDE4@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4600313
L10_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L10_1.m_Pos = "L"
L10_1.m_bCharPinup = true
L11_1 = "편지가 좋을까? 아니면 전광판에 깜짝 등장?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "手紙？　それともスクリーンにドッキリで登場する？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Would a letter be okay? Or maybe I should pop up in one of their billboards!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "要寫信嗎？還是在LED板上出現一下？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ส่งจดหมายดีมั้ยนะ? หรือฉันไปโผล่ในป้ายโฆษณาสักที่ดี?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Viết thư có được không? Hay có lẽ tôi nên xuất hiện trên mấy tấm biển quảng cáo của họ!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "写信怎么样？还是在大屏幕上闪亮登场？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Wie wäre es mit einem Brief? Oder vielleicht sollte ich auf einer ihrer Werbetafeln erscheinen!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Avec une lettre ? Oh, et si j'apparaissais dans leurs écrans pour leur lire un message ?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "NEVERLAND_ACT3_INTERLUDE4@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4600313
L11_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L11_1.m_Pos = "R"
L11_1.m_bCharPinup = true
L12_1 = "표현하지 않아도 전해질 거야. 그 사람들도 시그마 너만큼 고마워하고 있을 테니까."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "表現しなくても伝わるはずだよ。あの人たちもシグマくらいありがたく思ってるはずだから。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "They will know how grateful you are, even if you don’t say anything. Besides, I'm sure they will be thanking you more."
L11_1.m_Talk_ENG = L12_1
L12_1 = "不用刻意表達，他們也能感受到的，因為他們現在應該也很感謝你。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ต่อให้เธอไม่พูดอะไร พวกเขาก็ต้องรู้แหละว่าเธอซาบซึ้งขนาดไหน แถมฉันแน่ใจด้วยนะ ว่าพวกเขาจะขอบคุณเธอมากกว่านี้อีก"
L11_1.m_Talk_THA = L12_1
L12_1 = "Họ sẽ biết cậu biết ơn thế nào, ngay cả khi cậu chẳng nói gì. Ngoài ra, tôi dám chắc là họ còn cảm ơn cậu nhiều hơn."
L11_1.m_Talk_VTN = L12_1
L12_1 = "有些谢意其实不用刻意表达，也总会传达到的。而且我敢肯定，他们现在也一样很感谢你。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Sie werden wissen, wem sie zu danken haben, auch wenn wir nichts sagen. Außerdem bin ich mir sicher, dass sie dir noch mehr danken werden, Sigma."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ils comprendront même si tu ne dis rien. Et je suis sûre qu'ils te sont reconnaissants, eux aussi."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
