L16_1 = "NEVERLAND_ACT3_INTERLUDE4@215#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 215
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4600313
L15_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_DESPAIR"
L15_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L15_1.m_Pos = "C"
L16_1 = "루루, 갑자기 네 몸이 투명해 보여."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ルル、体がいきなり透けてみえるよ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Lulu...? Why can I see through you?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "露露，你的身體突然變透明咧？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ลูลู...? ทำไมฉันมองทะลุเธอได้อะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Lulu...? Tại sao tôi có thể nhìn xuyên qua cậu vậy?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "露露，你的身体突然变成透明的了。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Lulu ...? Warum kann ich durch dich durchschauen?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Lulu... ? Ton corps... il disparaît !"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "NEVERLAND_ACT3_INTERLUDE4@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4600313
L16_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_IDLE"
L16_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "피곤해서 그래. 본래 모습으로 돌아가려면 기운이 아주 많이 필요하거든."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "疲れたからだよ。本来の姿に戻るためには気力がいっぱい必要なの。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "I’m tired, that’s all. It takes a lot of energy to turn back into my original form."
L16_1.m_Talk_ENG = L17_1
L17_1 = "因為我太累的關係，要恢復原本的樣子，會需要花很多力氣。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ฉันแค่เหนื่อยแหละ การคืนร่างเดิมต้องใช้พลังงานเยอะเลย"
L16_1.m_Talk_THA = L17_1
L17_1 = "Vì tôi mệt đấy. Biến về bản thể tốn năng lượng dữ lắm."
L16_1.m_Talk_VTN = L17_1
L17_1 = "那是因为我累了。要想恢复本来的样子，需要很多精力。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich bin nur müde, das ist alles. Es braucht viel Energie, um wieder in meine ursprüngliche Form zurückzukehren."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Je suis fatiguée, c'est tout. Prendre ma forme d'origine me demande beaucoup d'énergie."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "NEVERLAND_ACT3_INTERLUDE4@217#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 217
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4600313
L17_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_SURPRISE"
L17_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L17_1.m_Pos = "C"
L18_1 = "그러면 어떡해? 백 밤 자면 나아?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "じゃあ、どうするの？　百回寝たら治る？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Then what do you do? Will you get better if you sleep a hundred nights?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "那怎麼辦？睡一百天的話可以嗎？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "แล้วเธอทำงานอะไรเหรอ? หลับสักร้อยวันจะดีขึ้นมั้ย?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Vậy cậu định làm gì? Liệu ngủ một trăm đêm có giúp cậu hồi phục không?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "那怎么办？睡一百个晚上就会好吗？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Was kannst du tun? Würde es helfen, hundert Nächte zu schlafen?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Qu'est-ce qu'on peut faire ? Ça ira mieux si tu dors 100 nuits ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "NEVERLAND_ACT3_INTERLUDE4@218#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 218
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4600313
L18_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_DESPAIR"
L18_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L18_1.m_Pos = "C"
L19_1 = "사람들이 나쁜 꿈을 꿀 때면."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "人が悪い夢を見るたびに。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "When people get nightmares..."
L18_1.m_Talk_ENG = L19_1
L19_1 = "前提是人有做惡夢。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เวลาที่คนฝันร้าย..."
L18_1.m_Talk_THA = L19_1
L19_1 = "Khi người ta gặp ác mộng..."
L18_1.m_Talk_VTN = L19_1
L19_1 = "除非人们又做起了噩梦。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Wenn Menschen Albträume bekommen ..."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Quand les gens font des cauchemars..."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "NEVERLAND_ACT3_INTERLUDE4@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 4600313
L19_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L19_1.m_Pos = "C"
L20_1 = "나는 달이 없는 밤, 긴 다리로 지붕 위를 넘어다니면서 꿈을 앗아가던 이물이니까."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "私は月のない夜、長い足で屋根の上を歩きながら夢を奪っていた異物だから。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "I am the moonless night. I am the stranger who crosses a long bridge up in the sky, taking people's dreams."
L19_1.m_Talk_ENG = L20_1
L20_1 = "因為我是在沒有月亮的晚上，用長長的腳越過屋頂，把夢奪走的異物。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ฉันคือค่ำคืนที่ไร้ดวงจันทร์ ฉันเป็นคนแปลกหน้าเดินข้ามสะพานที่ทอดยาวขึ้นไปบนท้องฟ้า ที่เอาความฝันของผู้คนไป"
L19_1.m_Talk_THA = L20_1
L20_1 = "Tôi là đêm không trăng. Tôi là kẻ lạ mặt đi dọc cây cầu dài trên bầu trời, lấy đi giấc mơ của mọi người."
L19_1.m_Talk_VTN = L20_1
L20_1 = "因为我是在没有月亮的夜晚，甩着长腿在屋顶上转悠，夺走人们梦境的怪物。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Bin ich die mondlose Nacht. Ich bin die Fremde, die eine lange Brücke am Himmel überquert und die Träume der Menschen mitnimmt."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Je suis la nuit sans lune, celle qui traverse le pont du firmament en volant les rêves des gens."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "NEVERLAND_ACT3_INTERLUDE4@220#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 220
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 4600313
L20_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_SURPRISE"
L20_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L20_1.m_Pos = "C"
L21_1 = "꿈을……?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "夢を……？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Dreams...?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "把夢……？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ความฝันเหรอ...?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Giấc mơ...?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "梦境……？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Träume ...?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Les rêves... ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "NEVERLAND_ACT3_INTERLUDE4@221#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 221
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 4600313
L21_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_IDLE"
L21_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "응. 우리는 모두 그래."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "うん。私たちはみんなそうなの。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Yes. We're all like that."
L21_1.m_Talk_ENG = L22_1
L22_1 = "嗯，我們都這樣。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ใช่ เราเป็นแบบนั้นกันหมดแหละ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Đúng. Tất cả chúng ta đều như vậy."
L21_1.m_Talk_VTN = L22_1
L22_1 = "嗯，我们全都是这样的。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ja. Wir sind alle so."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Oui. C'est ce que nous sommes."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "NEVERLAND_ACT3_INTERLUDE4@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 4600313
L22_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "오로치도. 나도. 패러독스도."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "オロチも。私も。パラドックスも。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Orochi, me, and Paradox."
L22_1.m_Talk_ENG = L23_1
L23_1 = "無論是大蛇，或我，或悖論都是。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "โอโรจิ ฉัน หรือแม้แต่พาราด็อกซ์..."
L22_1.m_Talk_THA = L23_1
L23_1 = "Orochi, tôi, và thậm chí cả Paradox..."
L22_1.m_Talk_VTN = L23_1
L23_1 = "大蛇，我，还有悖论……"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Orochi, ich und sogar Paradox ..."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Orochi, moi, et même Paradoxe..."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "NEVERLAND_ACT3_INTERLUDE4@223#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 4600313
L23_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "동류들과 다르게, 각자의 이유로 어울려 사는 길 대신 옛날 그 시절에 남아 버렸어."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "みんなとは違って、それぞれの理由で一緒には暮らさずに昔の時代に残っちゃったの。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Unlike my peers, we all went our separate ways instead of living together, but we remain in the old days because of our own reasons."
L23_1.m_Talk_ENG = L24_1
L24_1 = "我和同類不同，因為各自的理由沒有選擇合適的路，而是留在以前。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฉันไม่เหมือนคนอื่นๆ เราต่างไปในทางของตัวเองแทนที่จะอยู่ด้วยกัน แต่นั่นก็ทำให้เรายังตกติดอยู่กับวันวาน"
L23_1.m_Talk_THA = L24_1
L24_1 = "Không giống như những người bạn khác của tôi, chúng ta rẽ theo những ngả đường khác nhau dù sống cùng nhau, nhưng chúng ta vẫn mãi nhớ về những kỷ niệm yêu dấu."
L23_1.m_Talk_VTN = L24_1
L24_1 = "与同类不同，因为各自的原因没能一起生活，而是留在过去那个时代了。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Im Gegensatz zu meinen Kollegen gingen wir alle getrennte Wege, anstatt zusammen zu leben, aber wir stecken deswegen in der Vergangenheit fest."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Contrairement à nos pairs, nous nous sommes séparées. Et au lieu de vivre ensemble en harmonie, nous restons piégées dans le passé."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "NEVERLAND_ACT3_INTERLUDE4@224#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 4600313
L24_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "UNIT_LAUGH"
L24_1.m_Face = L25_1
L24_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L24_1.m_Pos = "C"
L25_1 = "그러니까…… 잠시 떠나야 해."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "だから……しばらく離れないと。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "So... I have to leave for a while."
L24_1.m_Talk_ENG = L25_1
L25_1 = "所以……我要暫時離開。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ฉันก็เลย... คงต้องหายไปสักพัก"
L24_1.m_Talk_THA = L25_1
L25_1 = "Vậy nên... tôi phải rời đi một thời gian."
L24_1.m_Talk_VTN = L25_1
L25_1 = "所以……我必须暂时离开了。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Also ... muss ich für eine Weile gehen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "L'heure est venue pour moi... de partir."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "NEVERLAND_ACT3_INTERLUDE4@225#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 4600313
L25_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "나 때문에 다른 애들도 깨어나면 모두에게 폐를 끼칠 테니까."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "私のせいで他の子たちも目を覚めたらみんなに迷惑になるはずだから。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I don't want the others to wake up because of me."
L25_1.m_Talk_ENG = L26_1
L26_1 = "要是因為我而喚醒其他同類，對大家都有害。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ฉันไม่อยากให้คนอื่นต้องตื่นขึ้นมาเพราะฉันน่ะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi không muốn những người khác thức dậy vì tôi."
L25_1.m_Talk_VTN = L26_1
L26_1 = "因为如果其他四凶神也因为我醒过来，会给所有人带来麻烦。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich möchte nicht, dass die anderen wegen mir aufwachen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Je ne veux pas que les autres se réveillent à cause de moi."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "NEVERLAND_ACT3_INTERLUDE4@226#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4600313
L26_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_DESPAIR"
L26_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L26_1.m_Pos = "C"
L27_1 = "그치만 루루가 떠나면 글린다가 슬퍼할 거야."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "でもルルがいなくなるとグリンダが悲しむよ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "But if you leave, Glinda will be sad, Lulu."
L26_1.m_Talk_ENG = L27_1
L27_1 = "可是露露離開的話，格琳達會難過的。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "แต่ถ้าเธอไป กลินดาจะเสียใจนะลูลู..."
L26_1.m_Talk_THA = L27_1
L27_1 = "Nhưng nếu cậu rời đi, Glinda sẽ buồn lắm, Lulu à..."
L26_1.m_Talk_VTN = L27_1
L27_1 = "可是露露离开的话，格琳达会伤心的。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Aber wenn du gehst, wird Glinda traurig sein, Lulu."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Mais Lulu, si tu pars Glinda va..."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "NEVERLAND_ACT3_INTERLUDE4@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 4600313
L27_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_IDLE"
L27_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "지금의 내가 곁에 있으면 아이들에게는 괴로운 앞날이 펼쳐져."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "今の私がそばにいても、子どもたちには辛い未来しか待ってない。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "If I stay, other children here will suffer."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我現在留下的話，以後只會帶給她們痛苦。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ถ้าฉันอยู่ พวกเด็กๆ ที่นี่ก็จะทรมานนะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Nếu tôi ở lại, bọn trẻ ở đây sẽ không thoải mái đâu."
L27_1.m_Talk_VTN = L28_1
L28_1 = "如果现在的我留下来，她们的未来会很痛苦。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Wenn das gegenwärtige Ich an deiner Seite ist, erwartet die Kinder eine schmerzhafte Zukunft."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Si je reste, tout le monde ici va souffrir."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
