L30_1 = "NEVERLAND_ACT3_INTERLUDE4@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 4600313
L29_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "UNIT_LAUGH"
L29_1.m_Face = L30_1
L29_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L29_1.m_Pos = "C"
L30_1 = "그럼 안녕. 너희 아빠에게 안부 전해 줘."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "それじゃあ、さよなら。あなたのパパによろしく伝えてね。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Goodbye for now. Say hello to your dad for me."
L29_1.m_Talk_ENG = L30_1
L30_1 = "再見，代替我向你爸爸問好。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ลากันไปก่อนแล้วกัน ฝากสวัสดีพ่อเธอให้ด้วยนะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Bây giờ thì tạm biệt nhé. Hãy giúp tôi chào bố của cậu."
L29_1.m_Talk_VTN = L30_1
L30_1 = "那么再见了，替我向你爸爸问好。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Auf Wiedersehen. Grüß deinen Vater von mir."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Adieu. Passe le bonjour à ton papa pour moi."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "NEVERLAND_ACT3_INTERLUDE4@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 4600313
L30_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L30_1.m_Pos = "C"
L31_1 = "루루, 우리 아빠랑 아는 사이였어?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ルル、私のパパと知り合いだったの？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Lulu, you know my Daddy?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "露露，你認識我爸爸嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ลูลู รู้จักพ่อฉันด้วยเหรอ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Lulu, cậu biết bố tôi sao?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "露露，你认识我爸爸吗？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Lulu, du kennst meinen Papa?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Tu connais mon papa ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "NEVERLAND_ACT3_INTERLUDE4@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 4600313
L31_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_PRIDE"
L31_1.m_Face = L32_1
L31_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "그럼. 내가 악몽을 거두게 된 계기인걸."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "もちろん。私が悪夢を取り込むようになったきっかけなの。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Of course. He's the reason I started harvesting nightmares."
L31_1.m_Talk_ENG = L32_1
L32_1 = "當然，他可是我收取惡夢的動機呢。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "รู้จักสิ เพราะเขานี่แหละ ฉันเลยเริ่มเก็บเกี่ยวฝันร้าย"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tất nhiên. Ông ấy là lý do khiến tôi bắt đầu thu hoạch ác mộng."
L31_1.m_Talk_VTN = L32_1
L32_1 = "当然。他是我结束噩梦的契机。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Natürlich. Er ist der Grund, warum ich anfing, Albträume zu ernten."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Bien sûr. C'est grâce à lui que j'ai commencé à collecter les cauchemars."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "NEVERLAND_ACT3_INTERLUDE4@232#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 232
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 4600313
L32_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_DESPAIR"
L32_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "무섭지만 다정하고, 강하지만 아픔도 많은 사람……."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "怖いけど優しい、強いけど傷も多い人……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "He's kind, yet scary. Strong, but is also in pain..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "他是既可怕又親切，既強悍又多愁善感的人……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เขาเป็นคนใจดี แต่ก็น่ากลัว เข้มแข็ง แต่ก็กำลังเจ็บปวดด้วย..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Ông ấy tốt bụng, nhưng đáng sợ. Mạnh mẽ, nhưng cũng nhiều đau đớn..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "可怕而多情，强大却有很多伤痛的人……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Er ist freundlich und doch beängstigend. Stark, aber auch von Schmerz geprägt ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Il est gentil, mais effrayant. Et malgré sa force, il souffre..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
