L35_1 = {}
L36_1 = "NEVERLAND_ACT3_INTERLUDE4@235#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 235
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 4600313
L35_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "UNIT_PRIDE"
L35_1.m_Face = L36_1
L35_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L35_1.m_Pos = "R"
L35_1.m_bCharPinup = true
L35_1.m_bCharPinupEasingTime = 0.25
L36_1 = "그 사람에게는 네가 필요해. 시그마. 항상 옆에서 힘이 되어 주길 바래."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "あの人にはあなたが必要よ、シグマ。いつもそばで力になってほしい。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "He needs you, Sigma. I want you to always stay by his side and help him."
L35_1.m_Talk_ENG = L36_1
L36_1 = "西格瑪，他需要你，希望你常常在他身邊，成為他的力量。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เขาต้องมีเธอนะซิกมา ฉันอยากให้เธอคอยช่วยเขาอยู่ข้างๆ ไปตลอด"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ông ấy cần cậu đấy, Sigma. Tôi muốn cậu hãy luôn ở cạnh và giúp ông ấy."
L35_1.m_Talk_VTN = L36_1
L36_1 = "那个人需要你，西格玛。希望你能一直在他身边成为他的力量。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Er braucht dich, Sigma. Ich möchte, dass du immer an seiner Seite bleibst und ihm hilfst."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Il a besoin de toi, Sigma. Tu dois rester à ses côtés, tu dois l'aider."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NEVERLAND_ACT3_INTERLUDE4@236#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 236
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 4600313
L36_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L36_1.m_Pos = "L"
L36_1.m_bCharPinup = true
L37_1 = "……응! 약속할게, 루루!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "……うん！　約束するよ、ルル！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "...Okay! I promise, Lulu!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "……好！我答應你，露露！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ได้เลย! ฉันสัญญานะลูลู!!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Được rồi! Tôi hứa mà, Lulu!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "……嗯！我保证，露露！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "... Okay! Ich verspreche es, Lulu!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "D'accord ! Je te le promets, Lulu !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NEVERLAND_ACT3_INTERLUDE4@237#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 237
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 4600313
L37_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "UNIT_LAUGH"
L37_1.m_Face = L38_1
L37_1.m_CharStrID = "NIGHTMARE_DREAM_NULL_NULL"
L37_1.m_Pos = "R"
L37_1.m_bCharPinup = true
L38_1 = "울지 않아 주는구나. 시그마는 착해."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "泣かないね。シグマはいい子だよ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "You're holding back your tears for me. You are such a kind girl, Sigma."
L37_1.m_Talk_ENG = L38_1
L38_1 = "你沒有哭呢，西格瑪好乖。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เธอกำลังกลั้นน้ำตาให้ฉันด้วย เธอเป็นเด็กดีจริงๆ นะซิกมา"
L37_1.m_Talk_THA = L38_1
L38_1 = "Cậu rưng rưng nước mắt vì tôi kìa. Cậu quả là một cô bé tốt bụng, Sigma à."
L37_1.m_Talk_VTN = L38_1
L38_1 = "你没有哭呢，西格玛真善良。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Du verkneifst dir gerade deine Tränen, oder? Du bist so ein nettes Mädchen, Sigma."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Tu retiens tes larmes pour moi... Tu es une fille si gentille, Sigma."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "NEVERLAND_ACT3_INTERLUDE4@238#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 238
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 4600313
L38_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L38_1.m_Pos = "L"
L38_1.m_bCharPinup = true
L39_1 = "잠시 떠날 뿐이잖아? 그럼 다시 만날 수 있어!"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "しばらく離れているだけでしょ？　じゃあ、また会える！"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Because you’ll only be gone for a little while, right? Then we'll be able to see each other again!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "你只是暫時離開而已不是嗎？那我們會再見面的！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ก็เธอจะหายไปแค่พักเดียวใช่มั้ยล่ะ? งั้นเดี๋ยวเราก็จะได้เจอกันอีกไง!"
L38_1.m_Talk_THA = L39_1
L39_1 = "Cậu chỉ đi trong một thời gian ngắn thôi phải không?Vậy chúng ta sẽ vẫn có thể gặp lại nhau được!"
L38_1.m_Talk_VTN = L39_1
L39_1 = "因为我知道，露露只是暂时离开呀？只要是再见，那就还能重逢！"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Weil du nur für kurze Zeit weg sein wirst, oder? Dann können wir uns wiedersehen!"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Tu vas revenir, non ? Et alors on pourra se revoir !"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "NEVERLAND_ACT3_INTERLUDE4@239#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 239
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 4600313
L39_1.m_CutScenStrID = "NEVERLAND_ACT3_INTERLUDE4"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "SIGMA_RAS_NEXT_NULL"
L39_1.m_Pos = "L"
L39_1.m_bCharPinup = true
L40_1 = "다시 만날 때는, 오늘보다 훨씬 재밌게 놀자!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "また会ったら、今日よりもっと楽しく遊ぼう！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "When we do, let's have more fun than we had today!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "下次見面時，要比今天玩得更開心喔！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "แล้วพอเจอกันอีก ก็มาสนุกกันให้มากกว่าวันนี้เถอะนะ!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Khi gặp lại nhau, hãy chơi nhiều trò vui cùng nhau hơn hôm nay nhé!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "重逢时，我们要比今天玩得更开心！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Wenn wir uns wiedersehen, lass uns noch mehr Spaß haben als heute!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "La prochaine fois, on s'amusera encore plus !"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
